 {\"layout\":{\"type\":\"flex\"}} -->\n<div class=\"wp-block-buttons\">\n<!-- wp:button {\"backgroundColor\":\"primary\",\"textColor\":\"on-primary\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-on-primary-color has-primary-background-color has-text-color has-background wp-element-button\" href=\"#upcoming-journeys\">Explore Workshops</a></div>\n<!-- /wp:button -->\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"#upcoming-journeys\">View Schedule</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative\"} -->\n<div class=\"wp-block-column relative\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"aspect-[4/5] rounded-xl overflow-hidden shadow-2xl relative rotate-2\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-[4/5] rounded-xl overflow-hidden shadow-2xl relative rotate-2\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuDkeVBlzSRkYoA2PRW_04xDyX_sT3yS2p7Q2H4WgzWz3v9vxxFRl-8_lpuXAl-LoekYqmgmBY6fpMdKa25aZc0vzIQf1nT6GGWzU2tmHdNjgplbIKyDCZiXPFwNBxo-zr62PpHoZPVpilp5SmfKTwY9LCljy451rK6Al36LlrhEnBbM0QdnaPSrS6K_SxNmSTkc17Drgx7lvosGNSW-L6Ko5ZwZNUBoW4vs6kyfEVtDgwl9sImnC8O0OHrjiLhjPdp4vC6kUgPFlQyo\" alt=\"Pottery studio in morning light\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"absolute -bottom-8 -left-8 p-8 bg-white/40 backdrop-blur-xl rounded-xl -rotate-3 border border-white/20 shadow-xl hidden md:block\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -bottom-8 -left-8 p-8 bg-white/40 backdrop-blur-xl rounded-xl -rotate-3 border border-white/20 shadow-xl hidden md:block\">\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl text-secondary mb-0\"} -->\n<p class=\"font-headline text-2xl text-secondary mb-0\">Sacred Space</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 bg-surface-container-low textured-bg\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 bg-surface-container-low textured-bg\">\n<!-- wp:group {\"className\":\"max-w-screen-2xl mx-auto px-6 md:px-12\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-screen-2xl mx-auto px-6 md:px-12\">\n<!-- wp:group {\"className\":\"text-center mb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group text-center mb-20\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl font-normal font-headline text-tertiary mb-4\"} -->\n<h2 class=\"wp-block-heading text-5xl font-normal font-headline text-tertiary mb-4\">Nurture Every Aspect</h2>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"flex justify-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group flex justify-center\">\n<!-- wp:paragraph {\"className\":\"h-1 w-24 bg-primary/20 rounded-full mb-0\"} -->\n<p class=\"h-1 w-24 bg-primary/20 rounded-full mb-0\" aria-hidden=\"true\"></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"3rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"w-16 h-16 rounded-full bg-secondary-container flex items-center justify-center mb-8 inline-flex\"><span class=\"material-symbols-outlined text-secondary text-3xl\">eco</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-normal font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-3xl font-normal font-headline text-on-surface\">The Earth</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant leading-relaxed text-lg\"} -->\n<p class=\"text-on-surface-variant leading-relaxed text-lg\">Pottery, soil health, and natural pigments. Working with the Alentejo clay is a meditative journey back to the roots of the peninsula.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"w-16 h-16 rounded-full bg-primary-container/30 flex items-center justify-center mb-8 inline-flex\"><span class=\"material-symbols-outlined text-primary text-3xl\">hand_gesture</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-normal font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-3xl font-normal font-headline text-on-surface\">The Craft</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant leading-relaxed text-lg\"} -->\n<p class=\"text-on-surface-variant leading-relaxed text-lg\">Woodwork, weaving, and metalwork. We value the patience of the hand and the honesty of raw, sustainably sourced materials.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"w-16 h-16 rounded-full bg-tertiary-container/30 flex items-center justify-center mb-8 inline-flex\"><span class=\"material-symbols-outlined text-tertiary text-3xl\">self_improvement</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-normal font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-3xl font-normal font-headline text-on-surface\">The Spirit</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant leading-relaxed text-lg\"} -->\n<p class=\"text-on-surface-variant leading-relaxed text-lg\">Movement, meditation, and storytelling. Aligning the creative body with the rhythm of the seasons and the cycle of the moon.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 px-6 md:px-12 max-w-screen-2xl mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 px-6 md:px-12 max-w-screen-2xl mx-auto\" id=\"upcoming-journeys\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-4xl md:text-5xl font-headline font-bold mb-16 text-center text-on-surface\"} -->\n<h2 class=\"wp-block-heading text-4xl md:text-5xl font-headline font-bold mb-16 text-center text-on-surface\">Upcoming Journeys</h2>\n<!-- /wp:heading -->\n<!-- wp:cover {\"url\":\"https://lh3.googleusercontent.com/aida-public/AB6AXuCDZdwXE8CWT-V_feq70zM4vc0OrqWGeyNFiWc-3Uu0a63Xe-J_MjjWdpjjnK2jQRigvf_nf6uU8BEu36BlEpoDW-z8Sb-_DWzxS9lvLBmxBY6BnzdM15F9z9On_WPTqrP2b0G9otDFmS4wNnLOoVJLglwCp-lLPMfDkvVbSq6LK3SU9VtfszdF1KHh7iYjFM_G0PmZtNVGgow1NNvHujNSlTGbBM2SyNkbVdwr25J0jPegRtHosiSuEvfE_Ha7MiqBSY6iptvL0JEn\",\"dimRatio\":50,\"minHeight\":360,\"className\":\"rounded-xl shadow-lg mb-8\"} -->\n<div class=\"wp-block-cover rounded-xl shadow-lg mb-8\" style=\"min-height:360px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-50\"></span><img class=\"wp-block-cover__image-background size-full\" alt=\"\" src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuCDZdwXE8CWT-V_feq70zM4vc0OrqWGeyNFiWc-3Uu0a63Xe-J_MjjWdpjjnK2jQRigvf_nf6uU8BEu36BlEpoDW-z8Sb-_DWzxS9lvLBmxBY6BnzdM15F9z9On_WPTqrP2b0G9otDFmS4wNnLOoVJLglwCp-lLPMfDkvVbSq6LK3SU9VtfszdF1KHh7iYjFM_G0PmZtNVGgow1NNvHujNSlTGbBM2SyNkbVdwr25J0jPegRtHosiSuEvfE_Ha7MiqBSY6iptvL0JEn\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:paragraph {\"className\":\"text-orange-200 text-sm font-label tracking-widest uppercase mb-2\"} -->\n<p class=\"text-orange-200 text-sm font-label tracking-widest uppercase mb-2\">12-18 October</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-white text-4xl font-headline font-semibold mb-2\"} -->\n<h3 class=\"wp-block-heading text-white text-4xl font-headline font-semibold mb-2\">Ancestral Pottery</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-white/90 max-w-md\"} -->\n<p class=\"text-white/90 max-w-md\">Unearth the secrets of Alentejo pit-firing and coiling techniques.</p>\n<!-- /wp:paragraph -->\n</div></div>\n<!-- /wp:cover -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 h-full flex flex-col justify-between\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 h-full flex flex-col justify-between\">\n<!-- wp:paragraph {\"className\":\"text-primary font-label text-sm uppercase tracking-widest mb-4\"} -->\n<p class=\"text-primary font-label text-sm uppercase tracking-widest mb-4\">Weekend Retreat</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-headline font-bold text-on-surface mb-4\"} -->\n<h3 class=\"wp-block-heading text-3xl font-headline font-bold text-on-surface mb-4\">Natural Flow: Movement &amp; Ink</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant\"} -->\n<p class=\"text-on-surface-variant\">A somatic exploration pairing dance with large-scale charcoal drawing.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"mt-8 mb-0\"} -->\n<p class=\"mt-8 mb-0\"><a class=\"text-tertiary font-semibold underline\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Learn more</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:cover {\"url\":\"https://lh3.googleusercontent.com/aida-public/AB6AXuD4DSUcSG-yI35ltZmRQQHN78dyLSjnvK26OatIaXMbv__MJXUzyKvJSLQ55K8vVp0c3Yr1rcfwqEQQYmXHDcmnSIgSTWFT9kj6zbNotPWBsLanBu7-Ukn-uZOkZ0XyB2EL8IlNmurA99O0ZFDxbA2rLlsIz8ObUZZNkNO85V13G6kAjHJaOnUzpaVE4hqVlP_HfLhdCn-EvCmjFKwx9hWBFoXxSs3EhdsvlxA65Ck2wzXt9TZeZs6Sd_HVas5nNw1MrQkI3J6g8976\",\"dimRatio\":40,\"minHeight\":280,\"className\":\"rounded-xl shadow-lg\"} -->\n<div class=\"wp-block-cover rounded-xl shadow-lg\" style=\"min-height:280px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-40\"></span><img class=\"wp-block-cover__image-background size-full\" alt=\"\" src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuD4DSUcSG-yI35ltZmRQQHN78dyLSjnvK26OatIaXMbv__MJXUzyKvJSLQ55K8vVp0c3Yr1rcfwqEQQYmXHDcmnSIgSTWFT9kj6zbNotPWBsLanBu7-Ukn-uZOkZ0XyB2EL8IlNmurA99O0ZFDxbA2rLlsIz8ObUZZNkNO85V13G6kAjHJaOnUzpaVE4hqVlP_HfLhdCn-EvCmjFKwx9hWBFoXxSs3EhdsvlxA65Ck2wzXt9TZeZs6Sd_HVas5nNw1MrQkI3J6g8976\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-white text-2xl font-headline font-bold\"} -->\n<h3 class=\"wp-block-heading text-white text-2xl font-headline font-bold\">Willow Weaving</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-white/90 text-sm mb-0\"} -->\n<p class=\"text-white/90 text-sm mb-0\">Traditional basketry for modern lives.</p>\n<!-- /wp:paragraph -->\n</div></div>\n<!-- /wp:cover -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:group {\"className\":\"bg-secondary-container/20 border border-secondary/10 rounded-xl p-8 mt-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-secondary-container/20 border border-secondary/10 rounded-xl p-8 mt-8\">\n<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:66.66%\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-headline font-bold text-secondary mb-4\"} -->\n<h3 class=\"wp-block-heading text-3xl font-headline font-bold text-secondary mb-4\">Forest Architecture</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-secondary-container text-lg italic mb-0\"} -->\n<p class=\"text-on-secondary-container text-lg italic mb-0\">\"Build with the trees, not against them. A deep dive into sustainable woodcrafting and cabin design.\"</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"33.33%\",\"className\":\"hidden sm:block\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center hidden sm:block\" style=\"flex-basis:33.33%\">\n<!-- wp:image {\"sizeSlug\":\"thumbnail\",\"linkDestination\":\"none\",\"className\":\"w-32 h-32 rounded-full mx-auto border-2 border-secondary/20\"} -->\n<figure class=\"wp-block-image size-thumbnail w-32 h-32 rounded-full mx-auto border-2 border-secondary/20\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuBZtrhITMbN4VqyTGDYxNNcIDFc6pn98iB_29RJ6OAmxNTPuI8jt3fJPZjJApIihScJ5t9cL9vfi0pMqkVdZIxDEnj4oJhl-YS8AAR8cVTvjX7GMVV9PynaRxptZRqku2J8uxSO5BkpnEbZx9pd7REZEXs0McS-G8-Hd5M3NfL84ikmVm1lmOR3izv8hKRGvT0aHjzoT-t6grr-sdWnFM7IGfidRvbC82RxOkGkC6ayEXSc79nxsAyGwz-hi9bmFtxrguV4CvPAruhT\" alt=\"Woodworking\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 bg-white\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 bg-white\">\n<!-- wp:group {\"className\":\"max-w-screen-xl mx-auto px-6 md:px-12\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-screen-xl mx-auto px-6 md:px-12\">\n<!-- wp:group {\"className\":\"bg-surface-container-low rounded-xl p-12 md:p-20 shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-low rounded-xl p-12 md:p-20 shadow-2xl\">\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"4rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-4xl md:text-5xl font-headline text-primary mb-8\"} -->\n<h2 class=\"wp-block-heading text-4xl md:text-5xl font-headline text-primary mb-8\">Earn Your Stay</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl text-on-surface-variant font-light italic\"} -->\n<p class=\"text-xl text-on-surface-variant font-light italic\">Are you a master of a craft, a keeper of ancient seeds, or a guide for the soul? Our community thrives on the circular exchange of wisdom.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-xl text-on-surface-variant font-light italic\"} -->\n<p class=\"text-xl text-on-surface-variant font-light italic\">Join our <strong>Skillshare Exchange</strong>. In exchange for hosting daily workshops or maintaining our gardens, residents can enjoy a reduced stay or full scholarship at Vila Akoya.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"className\":\"mt-10\"} -->\n<div class=\"wp-block-buttons mt-10\">\n<!-- wp:button {\"backgroundColor\":\"tertiary\",\"textColor\":\"on-primary\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-on-primary-color has-tertiary-background-color has-text-color has-background wp-element-button\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Propose an Exchange</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"33.33%\",\"className\":\"flex justify-center\"} -->\n<div class=\"wp-block-column flex justify-center\" style=\"flex-basis:33.33%\">\n<!-- wp:group {\"className\":\"relative w-64\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative w-64\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-64 h-80 rounded-[4rem] overflow-hidden border-8 border-white shadow-xl rotate-6 object-cover\"} -->\n<figure class=\"wp-block-image size-large w-64 h-80 rounded-[4rem] overflow-hidden border-8 border-white shadow-xl rotate-6 object-cover\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuAjiHintXKg8g-xsSKCjtKKPn_FSZ6ZOt8B5jNPdyHQAWDBf62tkQCQ6sZmMHWIgYamd7Yk1_tt4QXwKGQVnWog3YmI8f5YbT4P6H9KDA8bBTUtWb3Z3IwVozRrkGbUI_GGocbbK2BTCDkqMegRpfdgnzu20-HByILByIUOJwjCSrxpfFD50DqFOuRiNiopUFu4HZueiHPW2zJgxDIvryzGKijBIvPfPObwLNOmoYdxFwyb8xnx_n-WMX9y8g2FmzQoDXQu7L3T5Chj\" alt=\"Creative in workshop\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"absolute -top-4 -right-4 w-24 h-24 bg-secondary-container rounded-full flex items-center justify-center -rotate-12 border-4 border-white\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -top-4 -right-4 w-24 h-24 bg-secondary-container rounded-full flex items-center justify-center -rotate-12 border-4 border-white\">\n<!-- wp:paragraph {\"className\":\"font-label text-secondary text-sm mb-0\"} -->\n<p class=\"font-label text-secondary text-sm mb-0\">Join Us</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 px-6 md:px-12 max-w-screen-xl mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 px-6 md:px-12 max-w-screen-xl mx-auto\">\n<!-- wp:group {\"className\":\"text-center mb-16\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group text-center mb-16\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl font-headline text-on-surface mb-6\"} -->\n<h2 class=\"wp-block-heading text-5xl font-headline text-on-surface mb-6\">Host Your Own</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant max-w-2xl mx-auto text-lg\"} -->\n<p class=\"text-on-surface-variant max-w-2xl mx-auto text-lg\">Looking for a sanctuary to host your retreat? The Campus is open to outside facilitators who share our ethos of connection and creation.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:shortcode -->\n\n<!-- /wp:shortcode -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','The Campus','','inherit','closed','closed','','17-revision-v1','','','2026-04-05 11:18:51','2026-04-05 11:18:51','',17,'https://bisque-elk-240168.hostingersite.com/?p=32',0,'revision','',0),
(33,0,'2026-04-05 11:18:51','2026-04-05 11:18:51','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] flex flex-col justify-center px-6 md:px-12 lg:px-24 py-12 md:py-0 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] flex flex-col justify-center px-6 md:px-12 lg:px-24 py-12 md:py-0 mb-32\">\n<!-- wp:columns {\"className\":\"items-center\",\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}}} -->\n<div class=\"wp-block-columns items-center\">\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"z-10\"} -->\n<div class=\"wp-block-column z-10\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":1,\"className\":\"font-barrio text-6xl md:text-8xl text-primary mb-8 leading-none -rotate-2 origin-left\"} -->\n<h1 class=\"wp-block-heading font-barrio text-6xl md:text-8xl text-primary mb-8 leading-none -rotate-2 origin-left\">The Kids</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline italic text-2xl md:text-3xl text-on-surface-variant max-w-xl leading-relaxed\"} -->\n<p class=\"font-headline italic text-2xl md:text-3xl text-on-surface-variant max-w-xl leading-relaxed\">Where the ancient cork oaks become classrooms and the rhythm of the seasons dictates the curriculum.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative mt-12 lg:mt-0\"} -->\n<div class=\"wp-block-column relative mt-12 lg:mt-0\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"rounded-xl overflow-hidden aspect-[4/5] shadow-2xl rotate-3\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group rounded-xl overflow-hidden aspect-[4/5] shadow-2xl rotate-3\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuDGJroKCy58HsD_qv6wMP0wc4JOnWTPtKGxmEOQspLdbrI5TAxt5lvJV4BCweDo0qUxCPL2C-r5-fd8IHWJL6teC0K4d0B7GT2bBQWnF-Bs14vr-9QylbT2Q7fo5xTqEwBYiuPHseb1RdPDJw7muBU5cZSgvXH8bY_ks143Znh8RQzUkesHhEliG0EHWiviIHPSrB2KQlSvk9EC7qZZCAmZisg8s-A4Cj3-rMSiYXGmXZ54toYkOwzS3Z-AiXmFLyViAZtiiBz81gVh\" alt=\"Children among cork oaks\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"absolute -bottom-10 -left-10 w-48 h-48 rounded-full border-4 border-tertiary/20 flex items-center justify-center p-4 bg-surface/40 backdrop-blur-md hidden md:flex\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -bottom-10 -left-10 w-48 h-48 rounded-full border-4 border-tertiary/20 flex items-center justify-center p-4 bg-surface/40 backdrop-blur-md hidden md:flex\">\n<!-- wp:paragraph {\"className\":\"font-barrio text-tertiary text-center text-sm leading-tight rotate-12 mb-0\"} -->\n<p class=\"font-barrio text-tertiary text-center text-sm leading-tight rotate-12 mb-0\">Deeply Rooted</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"bg-surface-container-low py-24 md:py-32 rounded-xl mx-4 md:mx-8 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group bg-surface-container-low py-24 md:py-32 rounded-xl mx-4 md:mx-8 mb-32\">\n<!-- wp:group {\"className\":\"max-w-7xl mx-auto px-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-7xl mx-auto px-6\">\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"4rem\"}},\"className\":\"items-center\"} -->\n<div class=\"wp-block-columns items-center\">\n<!-- wp:column {\"className\":\"order-2 md:order-1 relative\"} -->\n<div class=\"wp-block-column order-2 md:order-1 relative\">\n<!-- wp:group {\"className\":\"bg-surface p-4 rounded-lg shadow-sm -rotate-3 mb-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface p-4 rounded-lg shadow-sm -rotate-3 mb-8\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-[500px] object-cover rounded-md\"} -->\n<figure class=\"wp-block-image size-large w-full h-[500px] object-cover rounded-md\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuBm_0MczpRcGBI9OJGkRgnO6Tt_5Mgd25_DWG-fUgTETnN8sFDs0JMR7n1SybR4ZvjlUhmBLLIGOx6wDACHEYTViPv-KsLxiyKoqbOxGnb4wRuzMZlS_hEIHeVjZR9jqBrClTOcU2VXJ_2VikSYJscoWN99uu_aWhxf5Y-c4gxTLhTCvHDcAXIxqOasL7f3Xi4M9dO_5VJPkADW4-zJMZwSnSHMaFBxKcJL-4fmhTqN2gd5_dtfREAt3sNuu3YRHhJR7cfqQbc2IQSi\" alt=\"Group of diverse children and parents sitting in a circle on woven rugs under a large tree, learning together\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"absolute top-1/2 -right-8 glass-effect bg-secondary-container/80 p-8 rounded-lg max-w-xs shadow-xl hidden lg:block\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute top-1/2 -right-8 glass-effect bg-secondary-container/80 p-8 rounded-lg max-w-xs shadow-xl hidden lg:block\">\n<!-- wp:paragraph {\"className\":\"font-headline text-on-secondary-container text-lg italic mb-0\"} -->\n<p class=\"font-headline text-on-secondary-container text-lg italic mb-0\">\"Our children don\'t just learn about the world; they learn within it.\"</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-1 md:order-2 space-y-8\"} -->\n<div class=\"wp-block-column order-1 md:order-2 space-y-8\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-4xl text-primary\"} -->\n<h2 class=\"wp-block-heading font-headline text-4xl text-primary\">The Homeschooling Collective</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg text-on-surface leading-relaxed\"} -->\n<p class=\"font-headline text-lg text-on-surface leading-relaxed\">A supportive ecosystem for families dedicated to alternative education. We provide the physical space and the communal spirit for curated learning journeys.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg text-on-surface leading-relaxed\"} -->\n<p class=\"font-headline text-lg text-on-surface leading-relaxed\">From collaborative project-based learning to shared resources, the collective operates on a philosophy of trust, autonomy, and the belief that every child is a natural researcher.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"pt-4 mb-0\"} -->\n<p class=\"pt-4 mb-0\"><a class=\"font-headline font-bold text-tertiary border-b-2 border-tertiary/30 hover:border-tertiary transition-all pb-1 text-xl inline-block\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Join the Circle</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"px-6 md:px-12 lg:px-24 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group px-6 md:px-12 lg:px-24 mb-32\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl text-primary text-center mb-20\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl text-primary text-center mb-20\">Daily Extracurriculars</h2>\n<!-- /wp:heading -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 flex flex-col justify-between h-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 flex flex-col justify-between h-full\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"w-16 h-16 bg-primary-container rounded-full flex items-center justify-center mb-8 inline-flex\"><span class=\"material-symbols-outlined text-on-primary-container text-3xl\">brush</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-primary mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-primary mb-4\">Manual Crafts</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg opacity-80 mb-8\"} -->\n<p class=\"font-headline text-lg opacity-80 mb-8\">Pottery with local clay, weaving with natural fibers, and woodcarving using fallen branches.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden grayscale\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden grayscale\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuBFNpFpAWTS-HjaXgPcoUc5ap2Q9Id9qw-aRo4Y7zTXDk6MSP7JYoJ4E3x4BSs27YU0Gx5NAxA5qaJogVv96JgButQW_Ja8jKRWLldx0qSUiQgsXzomKFc_fPCDVB2X9PI_wXMKfLjboO3MzsZTAisJPL5OEG4ESD-xEflfb2TGu-omSxyWucfXt9MiPLBrdVR49-YKxTE_pyDU-b8Bf0eGWrGdorLVGQWGWD1MzNAvOc7w7TbRcIh5HrssyKKj6O5i4B-miMzJzGCj\" alt=\"Child at pottery wheel\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"md:translate-y-12\"} -->\n<div class=\"wp-block-column md:translate-y-12\">\n<!-- wp:group {\"className\":\"bg-secondary-container/30 rounded-xl p-8 flex flex-col justify-between h-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-secondary-container/30 rounded-xl p-8 flex flex-col justify-between h-full\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"w-16 h-16 bg-secondary-container rounded-full flex items-center justify-center mb-8 inline-flex\"><span class=\"material-symbols-outlined text-secondary text-3xl\">forest</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-secondary mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-secondary mb-4\">Eco-Tracking</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg opacity-80 mb-8\"} -->\n<p class=\"font-headline text-lg opacity-80 mb-8\">Identifying flora and fauna, understanding soil health, and learning the language of the birds.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden grayscale\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden grayscale\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuB8joh7EBQxw0w-2Ibpm_TXuDeMvFWdctJDqCrl9jh91UOLLqM4dBgfMqOysCuhaMagkzkEmz2S_WPiIzBcWh_mPSbF3RB3BBiOqCwgtuK_-wPF66wNyrrgEdsH0Si60aw5P8wGW_G7veAAzkiRFl6D8768hDYVY1qyCdjhzyNQI8ADKoGYxSb_bTWAfxU0e_eAemO45h3DDy-4HZNLV60Pe2FDCScQbl1o-wAG7w5a2Gxfqyupk77T0V8qU7dTyuXg6XnlEK-yw3ZA\" alt=\"Forest light\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-tertiary-container/30 rounded-xl p-8 flex flex-col justify-between h-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-tertiary-container/30 rounded-xl p-8 flex flex-col justify-between h-full\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"w-16 h-16 bg-tertiary-container rounded-full flex items-center justify-center mb-8 inline-flex\"><span class=\"material-symbols-outlined text-on-tertiary-container text-3xl\">skillet</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-tertiary mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-tertiary mb-4\">Garden-to-Table</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg opacity-80 mb-8\"} -->\n<p class=\"font-headline text-lg opacity-80 mb-8\">Harvesting from our permaculture gardens and preparing wholesome, communal meals.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden grayscale\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden grayscale\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuBSWIneVqa6_LAzvG9eXHLKT67yT3DxvE05yPlb_HlsUlzzBQ8_PduU6AN_oB0SpYRQrr9xavaVVefcr5Hm6WiNmr69qC93VrrAD2bIW1GvXTxdHo7PmdPor0Bthoy2aLZpi081DZQGYWsgt8IhQL_BtKyomKSogbgZlj-JXv_MOQYAc7NRLUYR-nmDTm-zgrF-Sg7vH13fXCMblPfsSep-hD6Qny5EiQuT---_glgh6Q4hckOHv-tbjulLSBjZJbMvdatWma-fqfbL\" alt=\"Fresh vegetables\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative py-32 overflow-hidden bg-primary/5\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative py-32 overflow-hidden bg-primary/5\">\n<!-- wp:group {\"className\":\"max-w-4xl mx-auto px-6 relative text-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-4xl mx-auto px-6 relative text-center\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl md:text-7xl text-primary mb-12\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl md:text-7xl text-primary mb-12\">Wisdom of the Woods</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl md:text-3xl italic text-on-surface leading-snug\"} -->\n<p class=\"font-headline text-2xl md:text-3xl italic text-on-surface leading-snug\">\"The trees are our elders. We teach children to listen to their silence, to respect their longevity, and to understand our place as stewards of this land.\"</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"flex justify-center mb-0\"} -->\n<p class=\"flex justify-center mb-0\"><span class=\"w-px h-24 bg-tertiary/40 inline-block\" aria-hidden=\"true\"></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"not-italic text-lg font-label uppercase tracking-widest text-tertiary mb-0\"} -->\n<p class=\"not-italic text-lg font-label uppercase tracking-widest text-tertiary mb-0\">Our Core Pillars</p>\n<!-- /wp:paragraph -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}},\"className\":\"pt-8\"} -->\n<div class=\"wp-block-columns pt-8\">\n<!-- wp:column {\"className\":\"p-6\"} -->\n<div class=\"wp-block-column p-6\">\n<!-- wp:heading {\"level\":4,\"className\":\"font-headline text-2xl text-primary mb-2\"} -->\n<h4 class=\"wp-block-heading font-headline text-2xl text-primary mb-2\">Resilience</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-base font-body opacity-70 mb-0\"} -->\n<p class=\"text-base font-body opacity-70 mb-0\">Learning to navigate the outdoor elements with grace and confidence.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"p-6\"} -->\n<div class=\"wp-block-column p-6\">\n<!-- wp:heading {\"level\":4,\"className\":\"font-headline text-2xl text-primary mb-2\"} -->\n<h4 class=\"wp-block-heading font-headline text-2xl text-primary mb-2\">Empathy</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-base font-body opacity-70 mb-0\"} -->\n<p class=\"text-base font-body opacity-70 mb-0\">Developing a deep connection with all living beings in the forest ecosystem.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"p-6\"} -->\n<div class=\"wp-block-column p-6\">\n<!-- wp:heading {\"level\":4,\"className\":\"font-headline text-2xl text-primary mb-2\"} -->\n<h4 class=\"wp-block-heading font-headline text-2xl text-primary mb-2\">Curiosity</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-base font-body opacity-70 mb-0\"} -->\n<p class=\"text-base font-body opacity-70 mb-0\">Nurturing the innate drive to question, explore, and create meaning.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"px-6 md:px-12 lg:px-24 py-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group px-6 md:px-12 lg:px-24 py-32\">\n<!-- wp:group {\"className\":\"bg-surface-container-highest rounded-[3rem] p-12 md:p-24 overflow-hidden relative\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-highest rounded-[3rem] p-12 md:p-24 overflow-hidden relative\">\n<!-- wp:columns {\"className\":\"items-stretch gap-0\"} -->\n<div class=\"wp-block-columns items-stretch gap-0\">\n<!-- wp:column {\"width\":\"55%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:55%\">\n<!-- wp:group {\"className\":\"relative z-10 max-w-xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative z-10 max-w-xl\">\n<!-- wp:paragraph {\"className\":\"font-headline text-primary text-xl mb-4\"} -->\n<p class=\"font-headline text-primary text-xl mb-4\">Seasonal Intake</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl md:text-6xl text-on-background mb-8 leading-tight\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl md:text-6xl text-on-background mb-8 leading-tight\">Enrol Your Child in Nature</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-xl mb-12 opacity-90\"} -->\n<p class=\"font-headline text-xl mb-12 opacity-90\">We offer weekly programs and seasonal camps for children aged 5-12. Experience the magic of The Kids at Vila Akoya.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\"}} -->\n<div class=\"wp-block-buttons\">\n<!-- wp:button {\"backgroundColor\":\"primary\",\"textColor\":\"on-primary\",\"className\":\"rounded-full\"} -->\n<div class=\"wp-block-button rounded-full\"><a class=\"wp-block-button__link has-on-primary-color has-primary-background-color has-text-color has-background wp-element-button\" href=\"mailto:Info@vila-akoya.com?subject=The%20Kids%20brochure\">Download Brochure</a></div>\n<!-- /wp:button -->\n<!-- wp:button {\"className\":\"is-style-outline rounded-full\"} -->\n<div class=\"wp-block-button is-style-outline rounded-full\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book a Visit</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"45%\",\"className\":\"hidden lg:block\"} -->\n<div class=\"wp-block-column hidden lg:block\" style=\"flex-basis:45%\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full min-h-[280px] object-cover opacity-50 rounded-2xl\"} -->\n<figure class=\"wp-block-image size-large w-full h-full min-h-[280px] object-cover opacity-50 rounded-2xl\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuCOoagvEROnCyYA2TRl2HdaQVr-phnQJi5Z7pcU0_b-KN656R7NRv8ZYnmaKZ0ygjcacLOm2YN4LggRiDD7aVBSaspVpuCdTb8tj2wtfBz2hiJWj8PJJE3CC2sy3u0EqyJSpeo5chTRVelNcCi4LhoG9atIZlwUcmfjUr7ZkO4-CL6soEnYKDKmYEZ9euHLzVlSAeLyBtw_zhic32td6Z7u1PdknysRf3-9jhtNBZ5QkzeiU98L_CewrNMEoxN18Ls7qBAPCOlKr-5T\" alt=\"Alentejo cork forest at dusk\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','The Kids','','inherit','closed','closed','','18-revision-v1','','','2026-04-05 11:18:51','2026-04-05 11:18:51','',18,'https://bisque-elk-240168.hostingersite.com/?p=33',0,'revision','',0),
(34,0,'2026-04-05 11:18:51','2026-04-05 11:18:51','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner pt-0 pb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 pb-20\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] max-w-screen-2xl mx-auto px-8 grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] max-w-screen-2xl mx-auto px-8 grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center\">\n<!-- wp:group {\"className\":\"lg:col-span-5 z-10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-5 z-10\">\n<!-- wp:paragraph {\"className\":\"font-label text-primary tracking-[0.2em] uppercase text-sm mb-4\"} -->\n<p class=\"font-label text-primary tracking-[0.2em] uppercase text-sm mb-4\">Get in Touch</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1,\"className\":\"font-headline text-6xl md:text-8xl text-on-surface leading-tight mb-8\"} -->\n<h1 class=\"wp-block-heading font-headline text-6xl md:text-8xl text-on-surface leading-tight mb-8\">Let\'s start <br><span class=\"text-primary font-headline\">your journey.</span></h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-xl text-on-surface-variant max-w-md leading-relaxed mb-12\"} -->\n<p class=\"font-body text-xl text-on-surface-variant max-w-md leading-relaxed mb-12\">Vila Akoya, named after our children, is a labor of love tucked into the heart of the Alentejo. We\'d love to welcome you to our community.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"lg:col-span-7 relative\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-7 relative\">\n<!-- wp:group {\"className\":\"rounded-xl overflow-hidden aspect-[4/5] md:aspect-[16/10] shadow-2xl\",\"layout\":{\"type\":\"default\"}} 