(78,1,'2026-04-05 15:05:10','2026-04-05 15:05:10','<!-- wp:group {\"className\":\"vila-page-inner pt-0 pb-20 px-6 max-w-screen-xl mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 pb-20 px-6 max-w-screen-xl mx-auto\"><!-- wp:group {\"tagName\":\"section\",\"className\":\"grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center min-h-[calc(100vh-6rem)] mb-24\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center min-h-[calc(100vh-6rem)] mb-24\"><!-- wp:group {\"className\":\"lg:col-span-7\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-7\"><!-- wp:paragraph {\"className\":\"text-primary font-label uppercase tracking-[0.2em] text-xs mb-4\"} -->\n<p class=\"text-primary font-label uppercase tracking-[0.2em] text-xs mb-4\">Begin Your Journey</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"font-headline text-5xl md:text-7xl text-on-background leading-[1.1] mb-8\"} -->\n<h1 class=\"wp-block-heading font-headline text-5xl md:text-7xl text-on-background leading-[1.1] mb-8\">An Invitation to <br> <span class=\"font-serif-italic\">Slow Living</span></h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"font-body text-lg md:text-xl text-on-surface-variant max-w-xl leading-relaxed\"} -->\n<p class=\"font-body text-lg md:text-xl text-on-surface-variant max-w-xl leading-relaxed\">Whether you\'re seeking a permanent plot in our village or a soul-recharging stay at our campsite, we welcome your curiosity.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"mt-8 inline-flex items-center space-x-3 bg-secondary/10 px-5 py-3 rounded-full text-secondary font-medium\"} -->\n<p class=\"mt-8 inline-flex items-center space-x-3 bg-secondary/10 px-5 py-3 rounded-full text-secondary font-medium\"><span class=\"material-symbols-outlined text-xl\" aria-hidden=\"true\">calendar_today</span><span class=\"text-sm\">Opening May 1st, 2026</span></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"lg:col-span-5 relative\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-5 relative\"><!-- wp:group {\"className\":\"aspect-[4/5] rounded-xl overflow-hidden shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-[4/5] rounded-xl overflow-hidden shadow-2xl\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover transform hover:scale-105 transition-transform duration-700\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover transform hover:scale-105 transition-transform duration-700\"><img src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuB0YO7RwzDaUBYXKWatnP-c3s1YNuEUYn9nNLqgcJUySFbisQ2mXzUAT24CCyVBwx9DoUq4rSTBoXh_rs86cenlRIxZ4kH-iF9V7HFXY3Z5UU19DlS_5Dhi1KZ1wrTKDiZZnwPWQ0fGDkZOAycv95LFi8ZMTDFQhulSQw5Vy291KYk80nSgOQ_pFPH_dUh9OShoPFYq53tA6pQpmpbrK0Mb_BLqqSGrPC_IxJTfNW6AwVOeSJlSWwna2x4Cgyc0QNxyPvVBWTB4Dy3v\" alt=\"Alentejo cork oak trees at golden hour\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"absolute -bottom-6 -left-6 bg-primary-container p-8 rounded-lg text-white max-w-[240px] hidden md:block\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -bottom-6 -left-6 bg-primary-container p-8 rounded-lg text-white max-w-[240px] hidden md:block\"><!-- wp:paragraph {\"className\":\"font-serif-italic text-2xl mb-2\"} -->\n<p class=\"font-serif-italic text-2xl mb-2\">Sustainable Sanctuary</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"text-xs uppercase tracking-widest opacity-80 mb-0\"} -->\n<p class=\"text-xs uppercase tracking-widest opacity-80 mb-0\">Alentejo, Portugal</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"5rem\"}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"className\":\"space-y-12\"} -->\n<div class=\"wp-block-column space-y-12\"><!-- wp:group {\"className\":\"space-y-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6\"><!-- wp:heading {\"className\":\"font-headline text-3xl text-primary\"} -->\n<h2 class=\"wp-block-heading font-headline text-3xl text-primary\">Inquiry Details</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"font-body text-on-surface-variant leading-relaxed\"} -->\n<p class=\"font-body text-on-surface-variant leading-relaxed\">We are building more than just homes; we are cultivating a community centered on creativity and nature. Please share your vision with us, and our concierge will reach out to discuss how Vila Akoya can fit into your story.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"gap-6\"} -->\n<div class=\"wp-block-columns gap-6\"><!-- wp:column {\"className\":\"bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\"} -->\n<div class=\"wp-block-column bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\"><!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"block space-y-4 no-underline text-inherit\" href=\"https://bisque-elk-240168.hostingersite.com/village/\"><span class=\"material-symbols-outlined text-primary text-3xl\" aria-hidden=\"true\">home_pin</span></a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-xl\"} -->\n<h3 class=\"wp-block-heading font-headline text-xl\"><a href=\"https://bisque-elk-240168.hostingersite.com/village/\" class=\"no-underline text-inherit\">Village Plots</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant leading-relaxed\"} -->\n<p class=\"text-sm text-on-surface-variant leading-relaxed\">Long-term leases for custom tiny houses. Community gardens and shared studios included.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\"} -->\n<div class=\"wp-block-column bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\"><!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"block space-y-4 no-underline text-inherit\" href=\"https://bisque-elk-240168.hostingersite.com/campsite/\"><span class=\"material-symbols-outlined text-secondary text-3xl\" aria-hidden=\"true\">camping</span></a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-xl\"} -->\n<h3 class=\"wp-block-heading font-headline text-xl\"><a href=\"https://bisque-elk-240168.hostingersite.com/campsite/\" class=\"no-underline text-inherit\">Campsite Stays</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant leading-relaxed\"} -->\n<p class=\"text-sm text-on-surface-variant leading-relaxed\">Curated escapes for days or weeks. Immerse yourself in The Kids and workshop life.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"className\":\"pt-8 border-t border-outline-variant/30 space-y-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group pt-8 border-t border-outline-variant/30 space-y-6\"><!-- wp:paragraph -->\n<p><a class=\"flex items-center space-x-4 group no-underline\" href=\"https://wa.me/351960446285\" rel=\"noopener noreferrer\" target=\"_blank\"><span class=\"inline-flex w-12 h-12 rounded-full bg-surface-container-high items-center justify-center group-hover:bg-primary/10 transition-colors\"><span class=\"material-symbols-outlined text-primary\" aria-hidden=\"true\">chat_bubble</span></span><span><span class=\"text-xs font-label uppercase tracking-widest text-on-surface-variant block\">Quick Connect</span><span class=\"font-body text-on-surface group-hover:text-primary transition-colors\">Message us on WhatsApp</span></span></a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a class=\"flex items-center space-x-4 group no-underline\" href=\"mailto:hello@vilaakoya.pt\"><span class=\"inline-flex w-12 h-12 rounded-full bg-surface-container-high items-center justify-center group-hover:bg-primary/10 transition-colors\"><span class=\"material-symbols-outlined text-primary\" aria-hidden=\"true\">mail</span></span><span><span class=\"text-xs font-label uppercase tracking-widest text-on-surface-variant block\">Direct Inquiry</span><span class=\"font-body text-on-surface group-hover:text-primary transition-colors\">hello@vilaakoya.pt</span></span></a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"bg-surface-container-lowest/95 backdrop-blur-sm border border-outline-variant/20 p-8 md:p-12 rounded-xl editorial-shadow relative overflow-hidden\"} -->\n<div class=\"wp-block-column bg-surface-container-lowest/95 backdrop-blur-sm border border-outline-variant/20 p-8 md:p-12 rounded-xl editorial-shadow relative overflow-hidden\"><!-- wp:group {\"className\":\"space-y-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-8\"><!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-primary mb-0\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-primary mb-0\">Reserve your dates</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant mb-0\"} -->\n<p class=\"text-sm text-on-surface-variant mb-0\">Choose check-in and check-out, add to cart, then complete secure payment (card via Stripe when configured).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"vila-wc-booking\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-wc-booking\"><!-- wp:shortcode -->\n[product_page id=\"22\"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"pt-8 border-t border-outline-variant/25 space-y-4\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group pt-8 border-t border-outline-variant/25 space-y-4\"><!-- wp:heading {\"level\":4,\"className\":\"font-headline text-lg text-on-background mb-0\"} -->\n<h4 class=\"wp-block-heading font-headline text-lg text-on-background mb-0\">Questions before you book?</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant mb-0\"} -->\n<p class=\"text-sm text-on-surface-variant mb-0\">Send us a note and we will get back to you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->','Booking','','inherit','closed','closed','','16-revision-v1','','','2026-04-05 15:05:10','2026-04-05 15:05:10','',16,'https://bisque-elk-240168.hostingersite.com/?p=78',0,'revision','',0),
