(246,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-home\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-home\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative w-full max-w-[1236px] mx-auto box-border px-8 pt-8 pb-10 mb-28 md:mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative w-full max-w-[1236px] mx-auto box-border px-8 pt-8 pb-10 mb-28 md:mb-32\">\n<!-- wp:group {\"className\":\"relative w-full rounded-xl overflow-hidden editorial-shadow md:min-h-[calc(100vh-140px)]\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative w-full rounded-xl overflow-hidden editorial-shadow md:min-h-[calc(100vh-140px)]\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill w-full aspect-[4/3] [&>img]:brightness-[0.85] md:absolute md:inset-0 md:h-full md:min-h-0 md:w-full md:aspect-auto\"} -->\n<figure class=\"wp-block-image size-full vila-img-fill w-full aspect-[4/3] [&>img]:brightness-[0.85] md:absolute md:inset-0 md:h-full md:min-h-0 md:w-full md:aspect-auto\"><img src=\"/wp-content/uploads/2026/05/home-hero-scaled.jpg\" alt=\"Vila Akoya home hero\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"relative flex flex-col justify-end bg-gradient-to-b from-surface-container/80 via-surface-container/95 to-surface-container p-6 sm:p-8 md:absolute md:inset-0 md:justify-center md:bg-gradient-to-t md:from-on-surface/35 md:via-on-surface/15 md:to-transparent md:p-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative flex flex-col justify-end bg-gradient-to-b from-surface-container/80 via-surface-container/95 to-surface-container p-6 sm:p-8 md:absolute md:inset-0 md:justify-center md:bg-gradient-to-t md:from-on-surface/35 md:via-on-surface/15 md:to-transparent md:p-20\">\n<!-- wp:group {\"className\":\"max-w-4xl space-y-6 md:text-on-primary\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-4xl space-y-6 md:text-on-primary\">\n<!-- wp:heading {\"level\":1,\"className\":\"text-5xl md:text-8xl font-barrio text-on-surface md:text-on-primary leading-tight\"} -->\n<h1 class=\"wp-block-heading text-5xl md:text-8xl font-barrio text-on-surface md:text-on-primary leading-tight\">The little village of our dreams</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-2xl text-on-surface-variant md:text-on-primary/90 font-light max-w-2xl leading-relaxed\"} -->\n<p class=\"text-lg md:text-2xl text-on-surface-variant md:text-on-primary/90 font-light max-w-2xl leading-relaxed\">A tiny house village, glamping and creative community bordering the river Mira in the south of Alentejo. An extraordinary place of creation, relaxation and inspiration that we get to share with our friends and friends disguised as strangers.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"className\":\"flex flex-wrap gap-4 pt-4\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons flex flex-wrap gap-4 pt-4\">\n<!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button px-8 py-4 bg-gradient-to-r from-primary to-primary-container text-on-primary rounded-xl font-medium text-lg hover:scale-95 transition-transform\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your stay</a></div>\n<!-- /wp:button -->\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button px-8 py-4 bg-primary/10 border border-primary/20 text-primary md:bg-surface-bright/20 md:border-white/20 md:text-on-primary rounded-xl font-medium text-lg hover:bg-primary/15 md:hover:bg-surface-bright/30 transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/campus/\">Tell me more!</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"mb-32 md:mb-40\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group mb-32 md:mb-40\">\n<!-- wp:columns {\"className\":\"min-h-[min(100vh,70rem)] md:min-h-[calc(100vh-6rem)] gap-0 vila-split-flush\"} -->\n<div class=\"wp-block-columns min-h-[min(100vh,70rem)] md:min-h-[calc(100vh-6rem)] gap-0 vila-split-flush\">\n<!-- wp:column {\"className\":\"relative group flex flex-col items-center p-10 md:p-20 lg:p-24 bg-surface-container-low transition-all duration-700 hover:bg-surface-container overflow-hidden\"} -->\n<div class=\"wp-block-column relative group flex flex-col items-center p-10 md:p-20 lg:p-24 bg-surface-container-low transition-all duration-700 hover:bg-surface-container overflow-hidden\">\n<!-- wp:html -->\n<div class=\"absolute -top-10 -left-10 w-64 h-64 bg-tertiary/5 rounded-full blur-3xl group-hover:bg-tertiary/10 transition-colors pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\",\"layout\":{\"type\":\"default\"},\"style\":{\"spacing\":{\"blockGap\":\"1.75rem\"}}} -->\n<div class=\"wp-block-group z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\">\n<!-- wp:paragraph {\"className\":\"text-tertiary text-2xl font-headline\"} -->\n<p class=\"text-tertiary text-2xl font-headline\">A place to stay</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":2,\"className\":\"text-6xl md:text-7xl font-barrio text-on-surface narrow-header\"} -->\n<h2 class=\"wp-block-heading text-6xl md:text-7xl font-barrio text-on-surface narrow-header\">The Village</h2>\n<!-- /wp:heading -->\n<!-- wp:separator {\"className\":\"h-1 w-24 bg-tertiary/20 mx-auto rounded-full border-0\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity h-1 w-24 bg-tertiary/20 mx-auto rounded-full border-0\"/>\n<!-- /wp:separator -->\n<!-- wp:paragraph {\"className\":\"text-xl font-light text-on-surface-variant italic\"} -->\n<p class=\"text-xl font-light text-on-surface-variant italic\">Unique tiny homes in all shapes and forms. A feast for the eye and a home for the kind. This is the little village we\'ve always been hoping to find.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6 [&>img]:grayscale-[0.15] hover:[&>img]:grayscale-0\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6 [&>img]:grayscale-[0.15] hover:[&>img]:grayscale-0\"><img src=\"/wp-content/uploads/2026/05/village-small.jpg\" alt=\"The Village\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"pt-6\"} -->\n<p class=\"pt-6\"><a class=\"font-headline font-bold text-lg text-tertiary-dim underline decoration-tertiary/40 underline-offset-8 hover:decoration-tertiary transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/village/\">Looking for a village?</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"relative group flex flex-col justify-center items-center p-10 md:p-20 lg:p-24 bg-secondary-container/30 transition-all duration-700 hover:bg-secondary-container/50 overflow-hidden\"} -->\n<div class=\"wp-block-column relative group flex flex-col justify-center items-center p-10 md:p-20 lg:p-24 bg-secondary-container/30 transition-all duration-700 hover:bg-secondary-container/50 overflow-hidden\">\n<!-- wp:html -->\n<div class=\"absolute -bottom-10 -right-10 w-64 h-64 bg-secondary/5 rounded-full blur-3xl group-hover:bg-secondary/10 transition-colors pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\",\"layout\":{\"type\":\"default\"},\"style\":{\"spacing\":{\"blockGap\":\"1.75rem\"}}} -->\n<div class=\"wp-block-group z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\">\n<!-- wp:paragraph {\"className\":\"text-secondary text-2xl font-headline\"} -->\n<p class=\"text-secondary text-2xl font-headline\">...or to visit</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":2,\"className\":\"text-6xl md:text-7xl font-barrio text-on-surface narrow-header\"} -->\n<h2 class=\"wp-block-heading text-6xl md:text-7xl font-barrio text-on-surface narrow-header\">The Campsite</h2>\n<!-- /wp:heading -->\n<!-- wp:separator {\"className\":\"h-1 w-24 bg-secondary/20 mx-auto rounded-full border-0\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity h-1 w-24 bg-secondary/20 mx-auto rounded-full border-0\"/>\n<!-- /wp:separator -->\n<!-- wp:paragraph {\"className\":\"text-xl font-light text-on-surface-variant italic\"} -->\n<p class=\"text-xl font-light text-on-surface-variant italic\">Want to dip you toe in our home-away-from home? Swing by, join our table, have a swim, build a treehouse, make a friend.. and leave forever changed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill group w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6 [&>img]:transition-transform [&>img]:duration-300 group-hover:[&>img]:scale-[1.02]\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill group w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6 [&>img]:transition-transform [&>img]:duration-300 group-hover:[&>img]:scale-[1.02]\"><img src=\"/wp-content/uploads/2026/05/campsite.jpeg\" alt=\"The Campsite\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"pt-6\"} -->\n<p class=\"pt-6\"><a class=\"font-headline font-bold text-lg text-secondary-dim underline decoration-secondary/40 underline-offset-8 hover:decoration-secondary transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your dates</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"max-w-[1236px] mx-auto box-border px-8 mb-32 md:mb-40\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group max-w-[1236px] mx-auto box-border px-8 mb-32 md:mb-40\">\n<!-- wp:columns {\"className\":\"gap-12 lg:gap-20 items-stretch vila-columns-stretch\"} -->\n<div class=\"wp-block-columns gap-12 lg:gap-20 items-stretch vila-columns-stretch\">\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"md:col-span-5 relative flex flex-col h-full min-h-0\"} -->\n<div class=\"wp-block-column md:col-span-5 relative flex flex-col h-full min-h-0\" style=\"flex-basis:41.66%\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill flex-1 w-full min-h-[min(26rem,55vh)] md:min-h-[min(32rem,72vh)] overflow-hidden rounded-[2.5rem] md:rounded-[3rem] editorial-shadow relative z-10 rotate-[-1.5deg]\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill flex-1 w-full min-h-[min(26rem,55vh)] md:min-h-[min(32rem,72vh)] overflow-hidden rounded-[2.5rem] md:rounded-[3rem] editorial-shadow relative z-10 rotate-[-1.5deg]\"><img src=\"/wp-content/uploads/2026/05/river.jpeg\" alt=\"River Mira\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"absolute bottom-[-2rem] right-[-2rem] glass-card bg-surface-bright/80 p-6 rounded-2xl editorial-shadow max-w-[200px] z-20 rotate-[3deg] hidden md:block\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute bottom-[-2rem] right-[-2rem] glass-card bg-surface-bright/80 p-6 rounded-2xl editorial-shadow max-w-[200px] z-20 rotate-[3deg] hidden md:block\">\n<!-- wp:paragraph {\"className\":\"text-sm leading-tight text-on-surface flex flex-col gap-2\"} -->\n<p class=\"text-sm leading-tight text-on-surface flex flex-col gap-2\"><span class=\"material-symbols-outlined text-primary text-4xl mb-2\" style=\"font-variation-settings:\'FILL\' 1\" aria-hidden=\"true\">favorite</span>A little village with a big heart.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"md:col-span-7 space-y-8 flex flex-col justify-center\"} -->\n<div class=\"wp-block-column md:col-span-7 space-y-8 flex flex-col justify-center\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-4xl md:text-6xl font-headline text-on-surface font-light leading-tight\"} -->\n<h3 class=\"wp-block-heading text-4xl md:text-6xl font-headline text-on-surface font-light leading-tight\">That little village <br><span class=\"text-primary italic\">we\'ve been looking for</span></h3>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"space-y-6 text-xl font-light text-on-surface-variant leading-relaxed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6 text-xl font-light text-on-surface-variant leading-relaxed\">\n<!-- wp:paragraph -->\n<p>We wanted to live in the forest, and raise our kids amongst the trees. But we did not want to do it alone. Frankly, we\'re done with doing everything alone! Who came up with that? Lucky for us, there are loads more people like us. So we got a bunch of fantastic humans together and set out to build the little village of our dreams.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Expect to find something fantastic in every corner of this space. With playgrounds for children and for grown-ups, areas for wellness and relaxation, spaces designed for connection, creation and celebration, and a full agenda of workshops, classes and activities for humans of all ages.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\":\"pt-4\"} -->\n<p class=\"pt-4\"><a class=\"group flex items-center gap-4 text-primary font-bold text-xl\" href=\"https://bisque-elk-240168.hostingersite.com/campus/\">Learn more about the activities for adults and kids<span class=\"material-symbols-outlined group-hover:translate-x-2 transition-transform\" aria-hidden=\"true\">arrow_right_alt</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative mb-32 md:mb-40 overflow-x-hidden bg-gradient-to-b from-[#ebe4d4] via-[#e8dcc8] to-[#e5d6c4] text-[#3d2a22]\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative mb-32 md:mb-40 overflow-x-hidden bg-gradient-to-b from-[#ebe4d4] via-[#e8dcc8] to-[#e5d6c4] text-[#3d2a22]\">\n<!-- wp:html -->\n<div class=\"absolute inset-0 pointer-events-none opacity-[0.35] bg-[radial-gradient(ellipse_at_30%_20%,rgba(154,63,33,0.08),transparent_50%),radial-gradient(ellipse_at_70%_80%,rgba(92,99,72,0.06),transparent_45%)]\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"relative max-w-[1236px] mx-auto box-border px-8 py-20 md:py-28\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative max-w-[1236px] mx-auto box-border px-8 py-20 md:py-28\">\n<!-- wp:group {\"tagName\":\"header\",\"className\":\"text-center max-w-3xl mx-auto mb-14 md:mb-20 space-y-4\",\"layout\":{\"type\":\"default\"}} -->\n<header class=\"wp-block-group text-center max-w-3xl mx-auto mb-14 md:mb-20 space-y-4\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-barrio text-5xl md:text-7xl text-on-surface leading-tight\"} -->\n<h2 class=\"wp-block-heading font-barrio text-5xl md:text-7xl text-on-surface leading-tight\">Who are we?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-tertiary text-xl md:text-2xl tracking-wide\"} -->\n<p class=\"font-headline text-tertiary text-xl md:text-2xl tracking-wide\">The family behind Vila Akoya</p>\n<!-- /wp:paragraph -->\n<!-- wp:separator {\"className\":\"h-px w-32 bg-tertiary/25 mx-auto rounded-full border-0\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity h-px w-32 bg-tertiary/25 mx-auto rounded-full border-0\"/>\n<!-- /wp:separator -->\n</header>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\">\n<!-- wp:column {\"className\":\"order-2 md:order-1 space-y-6\"} -->\n<div class=\"wp-block-column order-2 md:order-1 space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Joyaa</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">It takes a village to raise a child, and for us it took a child to build a village. Vila Akoya wouldn\'t be anything without our daughter Joyaa. It\'s with her in mind that we envision the village in which we want to raise her; a green and inspiring place with a vibrant community where she - and her brother - will get to grow, learn and adventure.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Joyaa is 10 years old now. She\'s creative, funny, kind, smart and a great friend to have… and did I mention she\'s creative?</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Joyaa spends her days building castles for beetles with leaves and sticks that she finds, while singing songs about the things that she sees on her way, and what she thinks about them.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Joyaa is the artiste in our family, she loves reading, drawing, making music and climbing trees; she carries a big smile and an even bigger heart. You\'ll feel it when you meet her - this little lady is someone special.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-1 md:order-2 flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column order-1 md:order-2 flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/joyaa.jpg\" alt=\"Joyaa smiling with a large autumn leaf\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\">\n<!-- wp:column {\"className\":\"order-2 md:order-1 space-y-6\"} -->\n<div class=\"wp-block-column order-2 md:order-1 space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Sammy</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">My name is Sammy. I am Joyaa and Akhoda\'s mother and Hans\'s partner.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Besides a mother and partner, I am many other things. I have an entrepreneurial mind and a heart for sustainability; I founded and ran sustainable clothing and baby brands, and spend the last 4 years working on Vila Akoya. Just like Joyaa I am creative, love making music, learning new things and like to work with my hands.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">I spent most of my adult life travelling the world, had Joyaa along the way, and about 6 years ago Hans joined us — or we him! Together we decided to settle down in Portugal to build our dream: Vila Akoya.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Hans said I should call myself the heart and soul of the project, and I will do so with a humble pride. I have a clear vision of the village we wish to build for our children and ourselves. A vision that I am grateful to get to share with so many others.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-1 md:order-2 flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column order-1 md:order-2 flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--blob-3 w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--blob-3 w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/sammy.jpg\" alt=\"Sammy and Joyaa smiling together outdoors\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\">\n<!-- wp:column {\"className\":\"flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--blob-2 w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--blob-2 w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/hans.jpg\" alt=\"Hans smiling with Joyaa leaning on his shoulder\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Hans</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Hans is the <em class=\"text-on-surface\">brains</em> and the <em class=\"text-on-surface\">muscles</em> behind Vila Akoya. He knows and learns about the possibles and impossibles surrounding our projects. He always finds answers to the difficult questions, and he does so by tirelessly reading through piles of documents, underlining all that\'s relevant and questioning all that can be questioned, then puts on his gloves and starts lifting whatever heavy needs lifting before brushing off his shirt to sit patiently with Joyaa working on her homework, or playing tirelessly with little Akhoda.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Hans has spent the last 8 years working in real estate. Before that he was a national champion fencer and fencing coach in Canada, ran an organic farm, holds a degree in Cognitive Science and Philosophy and studied and taught an Indian martial art called Kalaripayattu — pretty impressive, right?</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-12 md:mb-20 lg:mb-24\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-12 md:mb-20 lg:mb-24\">\n<!-- wp:column {\"className\":\"order-1 flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column order-1 flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--blob-4 w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--blob-4 w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/akhoda.jpg\" alt=\"Hans holding baby Akhoda\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-2 space-y-6\"} -->\n<div class=\"wp-block-column order-2 space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Little Akhoda</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">In summer 2024 this little guy made our family complete. Akhoda is such a wonderful little person; he is strong but kind, he loves his family and the forest and meets plants and creatures with gentle hands and great curiosity.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">For us he is a big inspiration to want to be our best selves — so that when he looks his big eyes up at us, he sees good people who work hard doing something beautiful and meaningful in the world. This project is exactly that, for us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"className\":\"max-w-4xl mx-auto text-center space-y-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-4xl mx-auto text-center space-y-8\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--wide w-full mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--wide w-full mx-auto\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/family.jpg\" alt=\"The family together in the forest in front of a large tree\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\":\"font-headline text-xl text-tertiary-dim italic\"} -->\n<p class=\"font-headline text-xl text-tertiary-dim italic\">More about us and the people around us, our story and what brought us here.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a class=\"inline-flex items-center gap-2 text-primary font-bold text-lg hover:underline underline-offset-4\" href=\"https://bisque-elk-240168.hostingersite.com/about/\">How we got here<span class=\"material-symbols-outlined text-xl\" aria-hidden=\"true\">arrow_forward</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"max-w-screen-xl mx-auto px-6 sm:px-8 mb-32 md:mb-40 editorial-shadow rounded-[2rem] md:rounded-[3rem] overflow-hidden items-stretch vila-columns-stretch gap-0 vila-split-flush md:min-h-[min(28rem,70vh)]\"} -->\n<div class=\"wp-block-columns alignfull max-w-screen-xl mx-auto px-6 sm:px-8 mb-32 md:mb-40 editorial-shadow rounded-[2rem] md:rounded-[3rem] overflow-hidden items-stretch vila-columns-stretch gap-0 vila-split-flush md:min-h-[min(28rem,70vh)]\">\n<!-- wp:column {\"width\":\"66.66%\",\"className\":\"bg-primary text-on-primary p-10 md:p-14 lg:p-16 flex flex-col justify-center min-h-0\"} -->\n<div class=\"wp-block-column bg-primary text-on-primary p-10 md:p-14 lg:p-16 flex flex-col justify-center min-h-0\" style=\"flex-basis:66.66%\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl md:text-7xl font-headline leading-tight\"} -->\n<h2 class=\"wp-block-heading text-5xl md:text-7xl font-headline leading-tight\">Join our digi-family</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl opacity-90 leading-relaxed font-light\"} -->\n<p class=\"text-xl opacity-90 leading-relaxed font-light\">Want to stay in the loop about what\'s happening on our little slice of paradise? Enter your email here, and we will try not to spam you too much with the things we are excited to share.</p>\n<!-- /wp:paragraph -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"187\" html_class=\"vila-cf7 vila-cf7--newsletter\"]\n<!-- /wp:shortcode -->\n<!-- wp:paragraph {\"className\":\"text-sm opacity-80\"} -->\n<p class=\"text-sm opacity-80\"><a class=\"underline hover:opacity-100\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Want to get in touch? Find our contact info here</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"33.33%\",\"className\":\"relative hidden md:block md:h-full bg-primary overflow-hidden min-h-[12rem] md:min-h-0\"} -->\n<div class=\"wp-block-column relative hidden md:block md:h-full bg-primary overflow-hidden min-h-[12rem] md:min-h-0\" style=\"flex-basis:33.33%\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill absolute inset-0 h-full w-full opacity-[0.45] [&>img]:object-center\"} -->\n<figure class=\"wp-block-image size-full vila-img-fill absolute inset-0 h-full w-full opacity-[0.45] [&>img]:object-center\"><img src=\"/wp-content/uploads/2026/05/home-newsletter.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n','Home','','inherit','closed','closed','','12-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',12,'https://bisque-elk-240168.hostingersite.com/?p=246',0,'revision','',0),
(247,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner pt-0 pb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 pb-20\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] flex flex-col justify-center max-w-[1236px] box-border mx-auto px-8 py-12 md:py-0 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] flex flex-col justify-center max-w-[1236px] box-border mx-auto px-8 py-12 md:py-0 mb-32\">\n<!-- wp:columns {\"className\":\"gap-12 items-center\"} -->\n<div class=\"wp-block-columns gap-12 items-center\">\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"z-10\"} -->\n<div class=\"wp-block-column z-10\" style=\"flex-basis:58.33%\">\n<!-- wp:paragraph {\"className\":\"font-label text-primary uppercase tracking-[0.2em] text-sm font-bold mb-4\"} -->\n<p class=\"font-label text-primary uppercase tracking-[0.2em] text-sm font-bold mb-4\">About</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1,\"className\":\"font-headline text-6xl md:text-8xl text-on-surface leading-[1.1] mb-8\"} -->\n<h1 class=\"wp-block-heading font-headline text-6xl md:text-8xl text-on-surface leading-[1.1] mb-8\">The little village of our dreams</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-xl text-on-surface-variant max-w-xl leading-relaxed\"} -->\n<p class=\"font-body text-xl text-on-surface-variant max-w-xl leading-relaxed\">With fantastic spaces for our kids to play, learn and grow, for our hooved, furred and winged friends to graze, hop and skip, and for our grown-ups to relax, learn, eat, work and create together.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative\"} -->\n<div class=\"wp-block-column relative\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"rounded-xl overflow-hidden aspect-[4/5] shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group rounded-xl overflow-hidden aspect-[4/5] shadow-2xl\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/about-hero.jpg\" alt=\"Founders in Alentejo\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"absolute -bottom-10 -left-20 hidden xl:block bg-secondary-container p-12 rounded-lg max-w-xs shadow-xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -bottom-10 -left-20 hidden xl:block bg-secondary-container p-12 rounded-lg max-w-xs shadow-xl\">\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl text-on-secondary-container leading-snug\"} -->\n<p class=\"font-headline text-2xl text-on-secondary-container leading-snug\">Bordering the beautiful river Mira</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"bg-surface-container-low py-32 rounded-xl mx-8 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group bg-surface-container-low py-32 rounded-xl mx-8 mb-32\">\n<!-- wp:group {\"className\":\"max-w-7xl mx-auto px-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-7xl mx-auto px-8\">\n<!-- wp:columns {\"className\":\"gap-20 items-center\"} -->\n<div class=\"wp-block-columns gap-20 items-center\">\n<!-- wp:column {\"className\":\"order-2 md:order-1\"} -->\n<div class=\"wp-block-column order-2 md:order-1\">\n<!-- wp:group {\"className\":\"rounded-lg overflow-hidden h-[500px]\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group rounded-lg overflow-hidden h-[500px]\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/about-what-is.jpg\" alt=\"Tiny house village in the forest\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-1 md:order-2\"} -->\n<div class=\"wp-block-column order-1 md:order-2\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl text-on-surface mb-8\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl text-on-surface mb-8\">What is Vila Akoya?</h2>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"space-y-6 font-body text-lg text-on-surface-variant leading-relaxed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6 font-body text-lg text-on-surface-variant leading-relaxed\">\n<!-- wp:paragraph -->\n<p>Think of a wholesome festival meets artistic campsite meets permaculture farm meets eco-village sort of space. Where we spend our days in the sun, surrounded by nature, art, great people, good food and clean water.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A place where our kids get to grow up in a healthy place, have their own homeschooling hub, and get to spend their days outdoor busy with lots of extracurricular activities, adventure and play.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>A place where we, the adults, get to spend time with our kids and our friends, and where we get to learn lots, grow foods, take care of the forest and of the animals, of ourselves, and each other and create one of the most fantastic and unique eco-campsites Portugal has ever seen. 🌈</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"max-w-[1236px] box-border mx-auto px-8 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group max-w-[1236px] box-border mx-auto px-8 mb-32\">\n<!-- wp:group {\"className\":\"grid grid-cols-1 md:grid-cols-4 md:grid-rows-2 gap-6 h-auto md:h-[600px]\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group grid grid-cols-1 md:grid-cols-4 md:grid-rows-2 gap-6 h-auto md:h-[600px]\">\n<!-- wp:group {\"className\":\"md:col-span-2 md:row-span-2 bg-primary text-on-primary p-12 rounded-xl flex flex-col justify-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group md:col-span-2 md:row-span-2 bg-primary text-on-primary p-12 rounded-xl flex flex-col justify-center\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl mb-6\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl mb-6\">Where is Vila Akoya?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg opacity-90 leading-relaxed\"} -->\n<p class=\"font-body text-lg opacity-90 leading-relaxed\">On a great central location along the IC1 - the scenic toll-free road connecting Lisbon to the Algarve - that\'s where you find us. Right on the border of Alentejo and the Algarve.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg opacity-90 leading-relaxed\"} -->\n<p class=\"font-body text-lg opacity-90 leading-relaxed\">When you\'re here it feels like you\'re far way from civilisation, but in reality, we\'re only minutes away from the town of Ourique.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg opacity-90 leading-relaxed mb-0\"} -->\n<p class=\"font-body text-lg opacity-90 leading-relaxed mb-0\">We fell in love as soon as we stepped foot on this little slice of paradise; the rolling hills, beautiful nature, cute little wooden structures, olive groves, cozy nooks and vast depths... and all of this bordering a river which, even at the end of the dry season, still was full of water. We feel really lucky to have found this place.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"md:col-span-2 bg-surface-container-highest rounded-xl overflow-hidden relative min-h-[240px] md:min-h-0\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group md:col-span-2 bg-surface-container-highest rounded-xl overflow-hidden relative min-h-[240px] md:min-h-0\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full min-h-[240px] md:min-h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full min-h-[240px] md:min-h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/about-where-is.jpg\" alt=\"Golden rolling hills of Alentejo at sunset\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"md:col-span-1 bg-secondary text-on-secondary p-8 rounded-xl flex flex-col justify-end min-h-[180px]\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group md:col-span-1 bg-secondary text-on-secondary p-8 rounded-xl flex flex-col justify-end min-h-[180px]\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-4xl mb-4 block\" aria-hidden=\"true\">park</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl mb-0\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl mb-0\">Surrounded by sees of green</h3>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"md:col-span-1 bg-tertiary-container text-on-tertiary p-8 rounded-xl flex flex-col justify-end min-h-[180px]\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group md:col-span-1 bg-tertiary-container text-on-tertiary p-8 rounded-xl flex flex-col justify-end min-h-[180px]\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-4xl mb-4 block\" aria-hidden=\"true\">explore</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl mb-0\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl mb-0\">Only 10 minutes from Ourique</h3>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"max-w-4xl mx-auto px-8 text-center py-20\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group max-w-4xl mx-auto px-8 text-center py-20\">\n<!-- wp:paragraph {\"className\":\"mb-6\"} -->\n<p class=\"mb-6\"><span class=\"material-symbols-outlined text-6xl text-primary\" style=\"font-variation-settings:\'FILL\' 1\" aria-hidden=\"true\">favorite</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl text-on-surface mb-8\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl text-on-surface mb-8\">Beautifully Different People</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-xl text-on-surface-variant leading-relaxed\"} -->\n<p class=\"font-body text-xl text-on-surface-variant leading-relaxed\">We believe the best group of people is a diverse group of people. At Vila Akoya we\'re excited to share our home and our table with wonderful humans of different backgrounds, ideas, skills and ages, in a place where we celebrate diversity and tolerance.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"className\":\"mt-12 flex flex-wrap justify-center gap-6\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons mt-12 flex flex-wrap justify-center gap-6\">\n<!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button bg-primary text-on-primary px-10 py-4 rounded-xl font-medium shadow-lg hover:shadow-primary/20 transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/village/\">More about The Village</a></div>\n<!-- /wp:button -->\n<!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button bg-surface-container-high text-on-surface px-10 py-4 rounded-xl font-medium transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/campsite/\">More about The Campsite</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','About','','inherit','closed','closed','','13-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',13,'https://bisque-elk-240168.hostingersite.com/?p=247',0,'revision','',0),
(248,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 mb-20 relative pb-12 md:pb-0 max-w-[1236px] mx-auto box-border\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 mb-20 relative pb-12 md:pb-0 max-w-[1236px] mx-auto box-border\">\n<!-- wp:columns {\"className\":\"gap-6 items-end md:items-center\"} -->\n<div class=\"wp-block-columns gap-6 items-end md:items-center\">\n<!-- wp:column {\"width\":\"58.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":1,\"className\":\"font-barrio text-6xl md:text-8xl text-primary leading-none mb-8 -rotate-1 origin-left\"} -->\n<h1 class=\"wp-block-heading font-barrio text-6xl md:text-8xl text-primary leading-none mb-8 -rotate-1 origin-left\">Our tiny house eco village</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl md:text-3xl italic text-tertiary max-w-xl mb-12\"} -->\n<p class=\"font-headline text-2xl md:text-3xl italic text-tertiary max-w-xl mb-12\">A little village of tiny houses and other out-of-the-ordinary living spaces.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative\"} -->\n<div class=\"wp-block-column relative\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"aspect-[4/5] rounded-xl overflow-hidden editorial-shadow\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-[4/5] rounded-xl overflow-hidden editorial-shadow\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/village-large.jpg\" alt=\"Modern tiny house with wooden cladding nestled in a cork oak forest under warm golden hour light\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"bg-surface-container-low py-32 px-6 md:px-20 overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group bg-surface-container-low py-32 px-6 md:px-20 overflow-hidden\">\n<!-- wp:group {\"className\":\"max-w-7xl mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-7xl mx-auto\">\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"5rem\"}},\"className\":\"items-center\"} -->\n<div class=\"wp-block-columns items-center\">\n<!-- wp:column {\"width\":\"50%\",\"className\":\"w-full md:w-1/2 relative\"} -->\n<div class=\"wp-block-column w-full md:w-1/2 relative\" style=\"flex-basis:50%\">\n<!-- wp:group {\"className\":\"relative z-10 aspect-square rounded-full border-[1.5rem] border-surface-container-high overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative z-10 aspect-square rounded-full border-[1.5rem] border-surface-container-high overflow-hidden\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/village-circle.jpg\" alt=\"Aerial view of rolling Alentejo hills with scattered olive trees\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"50%\",\"className\":\"w-full md:w-1/2\"} -->\n<div class=\"wp-block-column w-full md:w-1/2\" style=\"flex-basis:50%\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl font-bold text-on-surface mb-8\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl font-bold text-on-surface mb-8\">A Tiny Home Away From Home</h2>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"space-y-6 text-xl text-on-surface-variant leading-relaxed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6 text-xl text-on-surface-variant leading-relaxed\">\n<!-- wp:paragraph -->\n<p>One side of our project, which we call \"The Village\" is the more community-like part of our project; a car-free area with about 15 plots intended exclusively for tiny homes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Here a diverse crowd of fantastic humans of all sorts of different backgrounds, cultures and ages, spend longer stretches of time with us in their own tiny homes and other kinds of unique accommodations.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>We want this little village to be an inspiring place, so it is important to us is that these tiny homes are really beautiful, interesting, unique, weird, cute or absolutely fantastic, that they\'re built in a sustainable way and do not have a concrete foundation.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Every now and then we have some plots available for sale or for rent in our little village. If you\'d like to be considered for one of these spots, please get in touch with us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 px-6 md:px-20\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 px-6 md:px-20\">\n<!-- wp:group {\"className\":\"text-center mb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group text-center mb-20\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl text-primary mb-4\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl text-primary mb-4\">How to join our little village</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline italic text-2xl text-tertiary mb-0\"} -->\n<p class=\"font-headline italic text-2xl text-tertiary mb-0\">There are three ways in which to join our tiny house village</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}},\"className\":\"max-w-7xl mx-auto items-stretch vila-columns-stretch\"} -->\n<div class=\"wp-block-columns alignwide max-w-7xl mx-auto items-stretch vila-columns-stretch\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full group hover:bg-surface-bright transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full group hover:bg-surface-bright transition-colors duration-500\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 bg-secondary-container rounded-full flex items-center justify-center mb-8 group-hover:scale-110 transition-transform duration-300\"><span class=\"material-symbols-outlined text-on-secondary-container text-3xl\" aria-hidden=\"true\">landscape</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-3xl font-bold mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-3xl font-bold mb-4\">Tiny House Rental</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg text-on-surface-variant mb-8 grow\"} -->\n<p class=\"font-body text-lg text-on-surface-variant mb-8 grow\">Always wanted to stay in a tiny house, a converted double decker or a boat?<br><br>Find here our out-of-the-ordinary stays, available for short- and long term rental.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden mb-8\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden mb-8\"><img src=\"/wp-content/uploads/2026/05/village-rental.jpg\" alt=\"A cleared grassy plot surrounded by wild flowers and ancient trees, prepared for a eco-friendly tiny home\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"text-primary font-headline font-bold text-xl flex items-center gap-2 group-hover:translate-x-2 transition-transform duration-300\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Find the available rentals <span class=\"material-symbols-outlined\" aria-hidden=\"true\">arrow_right_alt</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full md:scale-105 z-10 group hover:bg-surface-bright transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full md:scale-105 z-10 group hover:bg-surface-bright transition-colors duration-500\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 bg-primary-container rounded-full flex items-center justify-center mb-8 group-hover:scale-110 transition-transform duration-300\"><span class=\"material-symbols-outlined text-on-primary-container text-3xl\" aria-hidden=\"true\">cottage</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-3xl font-bold mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-3xl font-bold mb-4\">5-year-lease</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg text-on-surface-variant mb-8 grow\"} -->\n<p class=\"font-body text-lg text-on-surface-variant mb-8 grow\">Have you fallen in love with our project and people, and want to put down some roots with us? Check here to see if we have any 5-year-lease spots available, to put down your own tiny home.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden mb-8\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden mb-8\"><img src=\"/wp-content/uploads/2026/05/village-5year.jpg\" alt=\"Interior of a cozy minimalist tiny house with large windows overlooking a forest\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"bg-primary text-on-primary px-8 py-3 rounded-full font-label font-semibold w-full inline-block text-center\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Get in touch</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full group hover:bg-surface-bright transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full group hover:bg-surface-bright transition-colors duration-500\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 bg-tertiary-container rounded-full flex items-center justify-center mb-8 group-hover:scale-110 transition-transform duration-300\"><span class=\"material-symbols-outlined text-on-tertiary-container text-3xl\" aria-hidden=\"true\">key</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-3xl font-bold mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-3xl font-bold mb-4\">Plot Purchase</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg text-on-surface-variant mb-8 grow\"} -->\n<p class=\"font-body text-lg text-on-surface-variant mb-8 grow\">Every now and then we have plots in our little village available for sale. If you\'re interested in one of these plots, please get in touch with us.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden mb-8\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden mb-8\"><img src=\"/wp-content/uploads/2026/05/village-plot.jpg\" alt=\"Elegant clay-colored villa with organic architecture and a stone terrace overlooking a valley at sunset\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"text-primary font-headline font-bold text-xl flex items-center gap-2 group-hover:translate-x-2 transition-transform duration-300\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Here <span class=\"material-symbols-outlined\" aria-hidden=\"true\">arrow_right_alt</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 bg-white/30\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 bg-white/30\">\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}},\"className\":\"px-6 md:px-20 items-center\"} -->\n<div class=\"wp-block-columns px-6 md:px-20 items-center\">\n<!-- wp:column {\"width\":\"33.33%\",\"className\":\"order-2 md:order-1\"} -->\n<div class=\"wp-block-column order-2 md:order-1\" style=\"flex-basis:33.33%\">\n<!-- wp:group {\"className\":\"aspect-square rounded-[3rem] overflow-hidden mb-4 rotate-3 editorial-shadow\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-square rounded-[3rem] overflow-hidden mb-4 rotate-3 editorial-shadow\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/village-cork.jpg\" alt=\"The cork oak forest and olive groves\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:heading {\"level\":5,\"className\":\"font-headline text-xl font-bold\"} -->\n<h5 class=\"wp-block-heading font-headline text-xl font-bold\">The cork oak forest and olive groves</h5>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"66.66%\",\"className\":\"order-1 md:order-2\"} -->\n<div class=\"wp-block-column order-1 md:order-2\" style=\"flex-basis:66.66%\">\n<!-- wp:group {\"className\":\"md:pl-12\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group md:pl-12\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-6xl text-on-surface mb-8\"} -->\n<h2 class=\"wp-block-heading font-headline text-6xl text-on-surface mb-8\">This land is our living room</h2>\n<!-- /wp:heading -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"relative group\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative group\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-[3/2] rounded-xl overflow-hidden mb-4 editorial-shadow\"} -->\n<figure class=\"wp-block-image size-large aspect-[3/2] rounded-xl overflow-hidden mb-4 editorial-shadow\"><img src=\"/wp-content/uploads/2026/05/village-river.jpg\" alt=\"Sunlight streaming through dense green forest foliage\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":5,\"className\":\"font-headline text-xl font-bold\"} -->\n<h5 class=\"wp-block-heading font-headline text-xl font-bold\">Bordering the river Mira</h5>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"mt-12 md:mt-24\"} -->\n<div class=\"wp-block-column mt-12 md:mt-24\">\n<!-- wp:group {\"className\":\"relative group\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative group\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-[3/2] rounded-xl overflow-hidden mb-4 editorial-shadow\"} -->\n<figure class=\"wp-block-image size-large aspect-[3/2] rounded-xl overflow-hidden mb-4 editorial-shadow\"><img src=\"/wp-content/uploads/2026/05/village-walking.jpg\" alt=\"Calm natural swimming pool with crystal clear water reflecting the blue sky\"/></figure>\n<!-- /wp:image -->\n<!-- wp:heading {\"level\":5,\"className\":\"font-headline text-xl font-bold\"} -->\n<h5 class=\"wp-block-heading font-headline text-xl font-bold\">Spectacular hiking and biking paths</h5>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 px-6 md:px-20 text-center\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 px-6 md:px-20 text-center\">\n<!-- wp:group {\"className\":\"max-w-6xl mx-auto bg-surface-container-high rounded-[4rem] p-12 md:p-24 relative overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-6xl mx-auto bg-surface-container-high rounded-[4rem] p-12 md:p-24 relative overflow-hidden\">\n<!-- wp:html -->\n<div class=\"absolute top-0 right-0 w-64 h-64 bg-primary/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"relative z-10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative z-10\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl md:text-7xl text-primary mb-8\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl md:text-7xl text-primary mb-8\">Want to learn more about our tiny home village?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-2xl italic text-tertiary mb-12 max-w-2xl mx-auto\"} -->\n<p class=\"font-body text-2xl italic text-tertiary mb-12 max-w-2xl mx-auto\">We\'ve prepared a beautiful document with more detailed information and long-term pricing.</p>\n<!-- /wp:paragraph -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"188\" html_class=\"vila-cf7 vila-cf7--newsletter\"]\n<!-- /wp:shortcode -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','Village','','inherit','closed','closed','','14-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',14,'https://bisque-elk-240168.hostingersite.com/?p=248',0,'revision','',0),
(249,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner pt-0 overflow-x-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 overflow-x-hidden\">\n\n<!-- wp:cover {\"url\":\"/wp-content/uploads/2026/05/campsite-hero-scaled.jpg\",\"dimRatio\":40,\"overlayColor\":\"primary\",\"isUserOverlayColor\":true,\"minHeight\":100,\"minHeightUnit\":\"vh\",\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-position-center-center\" style=\"min-height:100vh\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-40 has-primary-background-color\"></span><img class=\"wp-block-cover__image-background size-full\" alt=\"\" src=\"/wp-content/uploads/2026/05/campsite-hero-scaled.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:group {\"className\":\"w-full max-w-[1236px] mx-auto box-border px-8 space-y-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group w-full max-w-[1236px] mx-auto box-border px-8 space-y-8\">\n<!-- wp:heading {\"level\":1,\"className\":\"text-6xl md:text-8xl font-normal text-on-primary font-barrio leading-none drop-shadow-lg\"} -->\n<h1 class=\"wp-block-heading text-6xl md:text-8xl font-normal text-on-primary font-barrio leading-none drop-shadow-lg\">A Creative campsite</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl md:text-2xl text-on-primary font-light max-w-xl leading-relaxed\"} -->\n<p class=\"text-xl md:text-2xl text-on-primary font-light max-w-xl leading-relaxed\">A playground for kids and for adults, surrounded by seas of green as far as the eye can see.<br><br>Bring your own home-on-wheels or tent, all the people you love, and a story to share around the campfire.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"pt-6 mb-0\"} -->\n<p class=\"pt-6 mb-0\"><a class=\"inline-block px-10 py-5 bg-gradient-to-r from-primary to-primary-container text-on-primary rounded-xl text-lg font-semibold editorial-shadow hover:-translate-y-0.5 transition-all duration-300 text-center\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your plot</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 px-8 md:px-20 bg-surface\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 px-8 md:px-20 bg-surface\">\n<!-- wp:group {\"className\":\"max-w-[1236px] box-border mx-auto flex flex-col md:flex-row gap-20 items-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-[1236px] box-border mx-auto flex flex-col md:flex-row gap-20 items-center\">\n<!-- wp:group {\"className\":\"w-full md:w-1/2 space-y-10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group w-full md:w-1/2 space-y-10\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl md:text-7xl font-normal text-primary font-headline leading-tight\"} -->\n<h2 class=\"wp-block-heading text-5xl md:text-7xl font-normal text-primary font-headline leading-tight\">Spacious pitches<br/>Surrounded by nature</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl text-on-surface-variant font-light leading-relaxed\"} -->\n<p class=\"text-xl text-on-surface-variant font-light leading-relaxed\">We have 15 beautiful spacious camping pitches with decks, surrounded by proud trees, rolling hills and the singing of birds. Here our visitors can come and join us in their own campers, caravans or tents.</p>\n<!-- /wp:paragraph -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}},\"className\":\"pt-4\"} -->\n<div class=\"wp-block-columns pt-4\">\n<!-- wp:column {\"className\":\"space-y-2\"} -->\n<div class=\"wp-block-column space-y-2\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-tertiary text-4xl\" aria-hidden=\"true\">electrical_services</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":4,\"className\":\"font-bold text-lg\"} -->\n<h4 class=\"wp-block-heading font-bold text-lg\">With water and electricity</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant\"} -->\n<p class=\"text-sm text-on-surface-variant\">Available on every pitch</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-2\"} -->\n<div class=\"wp-block-column space-y-2\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-tertiary text-4xl\" aria-hidden=\"true\">pets</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":4,\"className\":\"font-bold text-lg\"} -->\n<h4 class=\"wp-block-heading font-bold text-lg\">Pet friendly</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant\"} -->\n<p class=\"text-sm text-on-surface-variant\">Fluffy friends are also more than welcome with us</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"w-full md:w-1/2 relative\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group w-full md:w-1/2 relative\">\n<!-- wp:group {\"className\":\"aspect-square rounded-full overflow-hidden border-8 border-surface-container shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-square rounded-full overflow-hidden border-8 border-surface-container shadow-2xl\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/campsite-pitches.jpg\" alt=\"Camping pitches surrounded by cork trees and open sky\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"absolute -top-10 -right-10 w-48 h-48 bg-tertiary-container rounded-full flex items-center justify-center p-8 text-center rotate-12 editorial-shadow\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -top-10 -right-10 w-48 h-48 bg-tertiary-container rounded-full flex items-center justify-center p-8 text-center rotate-12 editorial-shadow\">\n<!-- wp:paragraph {\"className\":\"font-headline text-on-tertiary-container text-xl leading-none mb-0\"} -->\n<p class=\"font-headline text-on-tertiary-container text-xl leading-none mb-0\">With access to all activities &amp; facilities</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 px-8 md:px-20 bg-surface-container-low\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 px-8 md:px-20 bg-surface-container-low\">\n<!-- wp:group {\"className\":\"max-w-[1236px] box-border mx-auto space-y-16\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-[1236px] box-border mx-auto space-y-16\">\n<!-- wp:group {\"className\":\"flex flex-col md:flex-row justify-between items-end gap-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group flex flex-col md:flex-row justify-between items-end gap-6\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-4xl md:text-6xl font-normal text-secondary font-headline\"} -->\n<h2 class=\"wp-block-heading text-4xl md:text-6xl font-normal text-secondary font-headline\">Activities &amp; Facilities</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"max-w-md text-on-surface-variant italic mb-0\"} -->\n<p class=\"max-w-md text-on-surface-variant italic mb-0\">The beautiful spaces we get to share together.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"bg-surface-container-high p-8 rounded-xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-high p-8 rounded-xl\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-5xl text-primary\" aria-hidden=\"true\">water</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-headline text-on-surface mt-6\"} -->\n<h3 class=\"wp-block-heading text-3xl font-headline text-on-surface mt-6\">The River Mira</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant\"} -->\n<p class=\"text-on-surface-variant\">Vila Akoya borders the river Mira, which hold water all-year-around. Have a swim, catch a fish, or take a little boat around!</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"mt-8 rounded-lg overflow-hidden h-48 object-cover\"} -->\n<figure class=\"wp-block-image size-large mt-8 rounded-lg overflow-hidden h-48 object-cover\"><img src=\"/wp-content/uploads/2026/05/campsite-river.jpg\" alt=\"River Mira and green banks\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}},\"className\":\"editorial-shadow\"} -->\n<div class=\"wp-block-columns editorial-shadow\">\n<!-- wp:column {\"className\":\"relative overflow-hidden\"} -->\n<div class=\"wp-block-column relative overflow-hidden\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-5xl text-tertiary\">palette</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-4xl font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-4xl font-headline text-on-surface\">Workshops</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant\"} -->\n<p class=\"text-on-surface-variant\">We\'re planning lots of workshops, classes and events for adults and children.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p class=\"mb-0\"><a class=\"text-primary font-bold decoration-primary/30 flex items-center gap-2\" href=\"https://bisque-elk-240168.hostingersite.com/campus/#upcoming-journeys\"\">View schedule here <span class=\"material-symbols-outlined\" aria-hidden=\"true\">arrow_forward</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover rounded-xl\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover rounded-xl\"><img src=\"/wp-content/uploads/2026/05/campsite-workshop.jpg\" alt=\"Hands messy with terracotta clay working a pottery wheel outdoors\"/></figure>\n<!-- /wp:image -->\n<!-- wp:html -->\n<div class=\"absolute -bottom-20 -right-20 opacity-5 pointer-events-none\" aria-hidden=\"true\">\n  <span class=\"material-symbols-outlined text-[300px]\">brush</span>\n</div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {\"url\":\"/wp-content/uploads/2026/05/campsite-little.jpg\",\"dimRatio\":50,\"minHeight\":280,\"className\":\"rounded-xl\"} -->\n<div class=\"wp-block-cover rounded-xl\" style=\"min-height:280px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-50\"></span><img class=\"wp-block-cover__image-background size-full\" alt=\"\" src=\"/wp-content/uploads/2026/05/campsite-little.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-4xl font-headline text-white\"} -->\n<h3 class=\"wp-block-heading text-4xl font-headline text-white\">For the littler ones</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"max-w-sm font-light text-white\"} -->\n<p class=\"max-w-sm font-light text-white\">We have loads of activities, a homeschooling collective, playgrounds, and a babysitter on-site!</p>\n<!-- /wp:paragraph -->\n</div></div>\n<!-- /wp:cover -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"1.5rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container p-8 rounded-xl h-full border border-outline-variant/10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container p-8 rounded-xl h-full border border-outline-variant/10\">\n<!-- wp:heading {\"level\":4,\"className\":\"text-2xl font-headline text-on-surface-variant uppercase tracking-tighter\"} -->\n<h4 class=\"wp-block-heading text-2xl font-headline text-on-surface-variant uppercase tracking-tighter\">Hiking and biking trails</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm\"} -->\n<p class=\"text-sm\">There are fantastic hiking and biking trails that start and end at Vila Akoya.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"mb-0 text-right\"} -->\n<p class=\"mb-0 text-right\"><span class=\"material-symbols-outlined text-tertiary\" aria-hidden=\"true\">hiking</span></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container-highest p-8 rounded-xl h-full border border-outline-variant/10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-highest p-8 rounded-xl h-full border border-outline-variant/10\">\n<!-- wp:heading {\"level\":4,\"className\":\"text-2xl font-headline text-on-surface-variant uppercase tracking-tighter\"} -->\n<h4 class=\"wp-block-heading text-2xl font-headline text-on-surface-variant uppercase tracking-tighter\">Food and Drinks</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm\"} -->\n<p class=\"text-sm\">Join our table for breakfast, lunch or dinner, and we will cook you up a feast!</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"mb-0 text-right\"} -->\n<p class=\"mb-0 text-right\"><span class=\"material-symbols-outlined text-primary\" aria-hidden=\"true\">restaurant</span></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 overflow-hidden\">\n<!-- wp:group {\"className\":\"px-8 md:px-20 mb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group px-8 md:px-20 mb-20\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-4xl md:text-7xl font-normal text-primary font-headline text-center\"} -->\n<h2 class=\"wp-block-heading text-4xl md:text-7xl font-normal text-primary font-headline text-center\">It\'s Beautiful Here</h2>\n<!-- /wp:heading -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"flex gap-8 px-8 overflow-x-auto pb-12 snap-x\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group flex gap-8 px-8 overflow-x-auto pb-12 snap-x\">\n<!-- wp:group {\"className\":\"min-w-[300px] md:min-w-[450px] shrink-0 snap-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group min-w-[300px] md:min-w-[450px] shrink-0 snap-center\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"rounded-xl aspect-[4/5] object-cover w-full\"} -->\n<figure class=\"wp-block-image size-large rounded-xl aspect-[4/5] object-cover w-full\"><img src=\"/wp-content/uploads/2026/05/campsite-slider-1.jpg\" alt=\"A vintage cream-colored van parked under a massive cork tree\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"min-w-[300px] md:min-w-[450px] shrink-0 snap-center mt-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group min-w-[300px] md:min-w-[450px] shrink-0 snap-center mt-20\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"rounded-xl aspect-[4/5] object-cover w-full\"} -->\n<figure class=\"wp-block-image size-large rounded-xl aspect-[4/5] object-cover w-full\"><img src=\"/wp-content/uploads/2026/05/campsite-slider-2.jpg\" alt=\"Interior of a bell tent with bohemian rugs and fairy lights\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"min-w-[300px] md:min-w-[450px] shrink-0 snap-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group min-w-[300px] md:min-w-[450px] shrink-0 snap-center\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"rounded-xl aspect-[4/5] object-cover w-full\"} -->\n<figure class=\"wp-block-image size-large rounded-xl aspect-[4/5] object-cover w-full\"><img src=\"/wp-content/uploads/2026/05/campsite-slider-3.jpg\" alt=\"Campfire under a starry sky\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"min-w-[300px] md:min-w-[450px] shrink-0 snap-center mt-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group min-w-[300px] md:min-w-[450px] shrink-0 snap-center mt-20\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"rounded-xl aspect-[4/5] object-cover w-full\"} -->\n<figure class=\"wp-block-image size-large rounded-xl aspect-[4/5] object-cover w-full\"><img src=\"/wp-content/uploads/2026/05/campsite-slider-4.jpg\" alt=\"Guest at sunset over rolling golden hills\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 px-8 text-center relative overflow-hidden bg-surface-container-low\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 px-8 text-center relative overflow-hidden bg-surface-container-low\">\n<!-- wp:html -->\n<div class=\"absolute -top-40 -left-40 w-96 h-96 bg-primary/5 rounded-full blur-3xl pointer-events-none\" aria-hidden=\"true\"></div>\n<div class=\"absolute -bottom-40 -right-40 w-96 h-96 bg-secondary/5 rounded-full blur-3xl pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"max-w-[50rem] mx-auto space-y-10 relative z-10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-[50rem] mx-auto space-y-10 relative z-10\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl md:text-7xl font-normal text-primary font-headline leading-none\"} -->\n<h2 class=\"wp-block-heading text-5xl md:text-7xl font-normal text-primary font-headline leading-none\">We are looking forward to meeting you!</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"max-w-2xl mx-auto text-xl font-light text-on-surface-variant\"} -->\n<p class=\"max-w-2xl mx-auto text-xl font-light text-on-surface-variant\">We are happy to host you and the humans and creatures that belong with you. Let us know your dates and needs, so we can reserve you a spot with us.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"flex flex-col sm:flex-row gap-6 justify-center items-center mb-0\"} -->\n<p class=\"flex flex-col sm:flex-row gap-6 justify-center items-center mb-0\"><a class=\"w-full sm:w-auto px-12 py-5 bg-primary text-on-primary rounded-xl font-bold text-lg editorial-shadow transition-transform hover:scale-105 active:scale-95 inline-block text-center\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your camping pitch</a><a class=\"w-full sm:w-auto px-12 py-5 border-2 border-primary text-primary rounded-xl font-bold text-lg hover:bg-primary/5 transition-colors inline-block text-center\" href=\"https://bisque-elk-240168.hostingersite.com/village/\">Look at the village</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','Campsite','','inherit','closed','closed','','15-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',15,'https://bisque-elk-240168.hostingersite.com/?p=249',0,'revision','',0),
(250,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner pt-0 pb-20 px-6 max-w-screen-xl mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 pb-20 px-6 max-w-screen-xl mx-auto\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center min-h-[calc(100vh-6rem)] mb-24\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center min-h-[calc(100vh-6rem)] mb-24\">\n<!-- wp:group {\"className\":\"lg:col-span-7\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-7\">\n<!-- wp:paragraph {\"className\":\"text-primary font-label uppercase tracking-[0.2em] text-xs mb-4\"} -->\n<p class=\"text-primary font-label uppercase tracking-[0.2em] text-xs mb-4\">There are many ways to</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1,\"className\":\"font-headline text-5xl md:text-7xl text-on-background leading-[1.1] mb-8\"} -->\n<h1 class=\"wp-block-heading font-headline text-5xl md:text-7xl text-on-background leading-[1.1] mb-8\">Join Vila Akoya</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg md:text-xl text-on-surface-variant max-w-xl leading-relaxed\"} -->\n<p class=\"font-body text-lg md:text-xl text-on-surface-variant max-w-xl leading-relaxed\">Whether you\'re looking for a place to stay for the night, for a month or for a lifetime, there is a place for you here with us!</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"mt-8 inline-flex items-center space-x-3 bg-secondary/10 px-5 py-3 rounded-full text-secondary font-medium\"} -->\n<p class=\"mt-8 inline-flex items-center space-x-3 bg-secondary/10 px-5 py-3 rounded-full text-secondary font-medium\"><span class=\"material-symbols-outlined text-xl\" aria-hidden=\"true\">calendar_today</span><span class=\"text-sm\">Opening May 1st, 2026</span></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"lg:col-span-5 relative\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-5 relative\">\n<!-- wp:group {\"className\":\"aspect-[4/5] rounded-xl overflow-hidden shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-[4/5] rounded-xl overflow-hidden shadow-2xl\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover transform hover:scale-105 transition-transform duration-700\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover transform hover:scale-105 transition-transform duration-700\"><img src=\"/wp-content/uploads/2026/05/booking-hero.jpg\" alt=\"Alentejo cork oak trees at golden hour\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"5rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column {\"className\":\"space-y-12\"} -->\n<div class=\"wp-block-column space-y-12\">\n<!-- wp:group {\"className\":\"space-y-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-3xl text-primary\"} -->\n<h2 class=\"wp-block-heading font-headline text-3xl text-primary\">How can we help you?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-on-surface-variant leading-relaxed\"} -->\n<p class=\"font-body text-on-surface-variant leading-relaxed\">We would love to know how you\'d like to be part our little village. Below you can find more information about the two sides of our project, and on the right you can get in touch with us to book your stay!</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"className\":\"gap-6\"} -->\n<div class=\"wp-block-columns gap-6\">\n<!-- wp:column {\"className\":\"bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\"} -->\n<div class=\"wp-block-column bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"block space-y-4 no-underline text-inherit\" href=\"https://bisque-elk-240168.hostingersite.com/village/\"><span class=\"material-symbols-outlined text-primary text-3xl\" aria-hidden=\"true\">home_pin</span></a></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-xl\"} -->\n<h3 class=\"wp-block-heading font-headline text-xl\"><a href=\"https://bisque-elk-240168.hostingersite.com/village/\" class=\"no-underline text-inherit\">The Village</a></h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant leading-relaxed\"} -->\n<p class=\"text-sm text-on-surface-variant leading-relaxed\">Where our villagers stay in tiny houses and other interesting homes-on-wheels.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\"} -->\n<div class=\"wp-block-column bg-surface-container-low p-8 rounded-lg space-y-4 hover:bg-surface-container-high transition-colors\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"block space-y-4 no-underline text-inherit\" href=\"https://bisque-elk-240168.hostingersite.com/campsite/\"><span class=\"material-symbols-outlined text-secondary text-3xl\" aria-hidden=\"true\">camping</span></a></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-xl\"} -->\n<h3 class=\"wp-block-heading font-headline text-xl\"><a href=\"https://bisque-elk-240168.hostingersite.com/campsite/\" class=\"no-underline text-inherit\">The Campsite</a></h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant leading-relaxed\"} -->\n<p class=\"text-sm text-on-surface-variant leading-relaxed\">Where our visitors visit us in their own home-on-wheels or tents.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n<!-- wp:group {\"className\":\"pt-8 border-t border-outline-variant/30 space-y-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group pt-8 border-t border-outline-variant/30 space-y-6\">\n<!-- wp:paragraph -->\n<p><a class=\"flex items-center space-x-4 group no-underline\" href=\"https://wa.me/351960446285\" rel=\"noopener noreferrer\" target=\"_blank\"><span class=\"inline-flex w-12 h-12 rounded-full bg-surface-container-high items-center justify-center group-hover:bg-primary/10 transition-colors\"><span class=\"material-symbols-outlined text-primary\" aria-hidden=\"true\">chat_bubble</span></span><span><span class=\"text-xs font-label uppercase tracking-widest text-on-surface-variant block\">Quick Connect</span><span class=\"font-body text-on-surface group-hover:text-primary transition-colors\">Message us on WhatsApp</span></span></a></p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a class=\"flex items-center space-x-4 group no-underline\" href=\"mailto:info@vila-akoya.com\"><span class=\"inline-flex w-12 h-12 rounded-full bg-surface-container-high items-center justify-center group-hover:bg-primary/10 transition-colors\"><span class=\"material-symbols-outlined text-primary\" aria-hidden=\"true\">mail</span></span><span><span class=\"text-xs font-label uppercase tracking-widest text-on-surface-variant block\">Direct Inquiry</span><span class=\"font-body text-on-surface group-hover:text-primary transition-colors\">info@vila-akoya.com</span></span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"va-booking-reserve-card vila-booking-card-shell bg-white border border-outline-variant/15 p-8 md:p-12 rounded-[3rem] editorial-shadow relative overflow-visible\"} -->\n<div class=\"wp-block-column va-booking-reserve-card vila-booking-card-shell bg-white border border-outline-variant/15 p-8 md:p-12 rounded-[3rem] editorial-shadow relative overflow-visible\">\n<!-- wp:group {\"className\":\"space-y-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-8\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-primary mb-0\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-primary mb-0\">Reserve your dates</h3>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"vila-wc-booking\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-wc-booking\">\n<!-- wp:shortcode -->\n[product_page id=\"22\"]\n<!-- /wp:shortcode -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"pt-8 border-t border-outline-variant/25 space-y-4\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group pt-8 border-t border-outline-variant/25 space-y-4\">\n<!-- wp:heading {\"level\":4,\"className\":\"font-headline text-lg text-on-background mb-0\"} -->\n<h4 class=\"wp-block-heading font-headline text-lg text-on-background mb-0\">Questions before you book?</h4>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm text-on-surface-variant mb-0\"} -->\n<p class=\"text-sm text-on-surface-variant mb-0\">Send us a note and we will get back to you.</p>\n<!-- /wp:paragraph -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"189\" html_class=\"vila-cf7 vila-cf7--booking\"]\n<!-- /wp:shortcode -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n','Booking','','inherit','closed','closed','','16-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',16,'https://bisque-elk-240168.hostingersite.com/?p=250',0,'revision','',0),
(251,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner bg-background text-on-background textured-bg\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner bg-background text-on-background textured-bg\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 py-12 md:py-0 max-w-[1236px] mx-auto box-border overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 py-12 md:py-0 max-w-[1236px] mx-auto box-border overflow-hidden\">\n<!-- wp:columns {\"className\":\"items-center\",\"style\":{\"spacing\":{\"blockGap\":\"3rem\"}}} -->\n<div class=\"wp-block-columns items-center\">\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"z-10\"} -->\n<div class=\"wp-block-column z-10\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":1,\"className\":\"text-6xl md:text-8xl font-normal font-barrio text-primary leading-none mb-8\"} -->\n<h1 class=\"wp-block-heading text-6xl md:text-8xl font-normal font-barrio text-primary leading-none mb-8\">The heart of our creative community</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl md:text-2xl font-light text-on-surface-variant max-w-xl leading-relaxed mb-12 italic\"} -->\n<p class=\"text-xl md:text-2xl font-light text-on-surface-variant max-w-xl leading-relaxed mb-12 italic\">We believe that it\'s important to learn something new every day. That\'s why at the heart of our project there\'s The Campus; A campus-meets-playground where villagers, guests, and visitors come together to learn and to share skills and ideas.<br><br>The Campus offers a daily program with a lively mix of classes, workshops, retreats, lectures and activities in all fields of life.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"flex flex-wrap gap-6 mb-0\"} -->\n<p class=\"flex flex-wrap gap-6 mb-0\"><a class=\"px-8 py-4 bg-gradient-to-r from-primary to-primary-container text-on-primary rounded-xl font-medium shadow-lg hover:shadow-xl transition-all inline-block text-center\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your dates</a><a class=\"px-8 py-4 font-headline font-bold text-tertiary underline decoration-tertiary/30 hover:decoration-tertiary transition-all inline-block\" href=\"https://bisque-elk-240168.hostingersite.com/the-kids/\">And what about the kids?</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative\"} -->\n<div class=\"wp-block-column relative\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"aspect-[4/5] rounded-xl overflow-hidden shadow-2xl relative rotate-2\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-[4/5] rounded-xl overflow-hidden shadow-2xl relative rotate-2\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/campus-hero.jpg\" alt=\"Sunlit pottery studio with rustic wooden tables, earthenware pots, and soft dust motes dancing in golden morning light\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 bg-surface-container-low textured-bg\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 bg-surface-container-low textured-bg\">\n<!-- wp:group {\"className\":\"max-w-[1236px] mx-auto box-border px-6 md:px-12\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-[1236px] mx-auto box-border px-6 md:px-12\">\n<!-- wp:group {\"className\":\"text-center mb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group text-center mb-20\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl font-normal font-headline text-tertiary mb-4\"} -->\n<h2 class=\"wp-block-heading text-5xl font-normal font-headline text-tertiary mb-4\">Classes in All Schools of Life</h2>\n<!-- /wp:heading -->\n<!-- wp:html -->\n<div class=\"h-1 w-24 bg-primary/20 mx-auto rounded-full\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"3rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 rounded-full bg-secondary-container flex items-center justify-center mb-8\"><span class=\"material-symbols-outlined text-secondary text-3xl\" aria-hidden=\"true\">self_improvement</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-normal font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-3xl font-normal font-headline text-on-surface\">Body &amp; Mind Wellness</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant leading-relaxed text-lg\"} -->\n<p class=\"text-on-surface-variant leading-relaxed text-lg\">Yoga, tai-chi, breathwork, meditation, somatics, martial arts and mindfulness.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 rounded-full bg-primary-container/30 flex items-center justify-center mb-8\"><span class=\"material-symbols-outlined text-primary text-3xl\" aria-hidden=\"true\">palette</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-normal font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-3xl font-normal font-headline text-on-surface\">Creative Arts</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant leading-relaxed text-lg\"} -->\n<p class=\"text-on-surface-variant leading-relaxed text-lg\">Ceramics, woodwork, natural building, weaving, photography, improv, painting, writing and music.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 rounded-full bg-tertiary-container/30 flex items-center justify-center mb-8\"><span class=\"material-symbols-outlined text-tertiary text-3xl\" aria-hidden=\"true\">construction</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-normal font-headline text-on-surface\"} -->\n<h3 class=\"wp-block-heading text-3xl font-normal font-headline text-on-surface\">Practical Skills</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant leading-relaxed text-lg\"} -->\n<p class=\"text-on-surface-variant leading-relaxed text-lg\">Permaculture, cooking, fermentation, foraging, herbal medicine, survival skills, first aid, beekeeping, composting, construction, carpentry, welding and sewing.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 relative overflow-hidden bg-white\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 relative overflow-hidden bg-white\">\n<!-- wp:group {\"className\":\"max-w-[1236px] mx-auto box-border px-6 md:px-12 relative z-10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-[1236px] mx-auto box-border px-6 md:px-12 relative z-10\">\n<!-- wp:group {\"className\":\"bg-surface-container-low rounded-xl p-12 md:p-20 shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-low rounded-xl p-12 md:p-20 shadow-2xl\">\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"4rem\"}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:66.66%\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-4xl md:text-5xl font-headline text-primary mb-8\"} -->\n<h2 class=\"wp-block-heading text-4xl md:text-5xl font-headline text-primary mb-8\">We\'re Looking For Artists, Teachers and Facilitators!</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl text-on-surface-variant font-light italic mb-0\"} -->\n<p class=\"text-xl text-on-surface-variant font-light italic mb-0\">If you have a great skill to share, and you would like to host workshops, events and/or classes on our project, to both adults and children? Let us know through the form below!</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"33.33%\",\"className\":\"flex justify-center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center flex justify-center\" style=\"flex-basis:33.33%\">\n<!-- wp:group {\"className\":\"relative w-64\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative w-64\">\n<!-- wp:group {\"className\":\"w-64 h-80 rounded-[4rem] overflow-hidden border-8 border-white shadow-xl rotate-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group w-64 h-80 rounded-[4rem] overflow-hidden border-8 border-white shadow-xl rotate-6\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/campus-teacher.jpg\" alt=\"Artist in a sun-drenched workshop\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:html -->\n<div class=\"absolute -top-4 -right-4 w-24 h-24 bg-secondary-container rounded-full flex items-center justify-center -rotate-12 border-4 border-white\"><span class=\"font-label text-secondary text-sm p-4 text-center\">Artist Residence</span></div>\n<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:html -->\n<div class=\"absolute top-0 right-0 w-96 h-96 bg-primary-container/10 blur-[120px] rounded-full -translate-y-1/2 translate-x-1/2 pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 px-6 md:px-12 max-w-[1300px] mx-auto box-border\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 px-6 md:px-12 max-w-[1300px] mx-auto box-border\">\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"2.5rem\"}},\"className\":\"items-start mb-14\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top items-start mb-14\">\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"58.33%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:58.33%\">\n<!-- wp:group {\"className\":\"bg-surface-container-low rounded-2xl p-8 md:p-10 shadow-sm\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-low rounded-2xl p-8 md:p-10 shadow-sm\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-4xl md:text-5xl font-headline text-on-surface mb-6\"} -->\n<h2 class=\"wp-block-heading text-4xl md:text-5xl font-headline text-on-surface mb-6\">Our wonderfully busy days</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant text-lg leading-relaxed mb-0\"} -->\n<p class=\"text-on-surface-variant text-lg leading-relaxed mb-0\">Start your day by dropping the kids at The Kids Hub before heading to the Campus, where this morning you get to choose between a yoga or ceramics class. Then treat yourself to a Thai massage before joining the communal lunch. In the afternoon, you might explore fermentation, join a mud-brick building workshop, or help create a mosaic path. Then end the day with an outdoor movie night, paired with a kombucha out of our own nano-brewery.<br><br>This is how we imagine our days here together. But for that, we need you!</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"41.66%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"rounded-2xl overflow-hidden shadow-xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group rounded-2xl overflow-hidden shadow-xl\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-[280px] md:h-[360px] object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-[280px] md:h-[360px] object-cover\"><img src=\"/wp-content/uploads/2026/05/campus-detail.jpg\" alt=\"People gathered in a creative outdoor campus space at golden hour\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2.5rem\"}},\"className\":\"mb-14\"} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"space-y-5\"} -->\n<div class=\"wp-block-column space-y-5\" style=\"flex-basis:58.33%\">\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant text-lg leading-relaxed\"} -->\n<p class=\"text-on-surface-variant text-lg leading-relaxed\">Curated workshops with outside facilitators and professionals will form the backbone of the program. We also offer artist residencies to people who add something special to our space.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant text-lg leading-relaxed\"} -->\n<p class=\"text-on-surface-variant text-lg leading-relaxed\">Besides these, residents and guests also have the opportunity to host more informal workshops, sharing their own skills with others. Here, you can choose to be a teacher one day and a student the next. This is one of the ways we weave our community; through sharing what we know with each other, and by learning new things together.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant text-lg leading-relaxed mb-0\"} -->\n<p class=\"text-on-surface-variant text-lg leading-relaxed mb-0\">Participation in these activities, like much within our project, is always based on invitation, not expectation. As a resident or visitor, you may choose to join all, some, or none of the activities that are offered.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"bg-secondary-container/30 border border-secondary/20 rounded-2xl p-7 md:p-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-secondary-container/30 border border-secondary/20 rounded-2xl p-7 md:p-8\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl font-headline text-secondary mb-5\"} -->\n<h3 class=\"wp-block-heading text-3xl font-headline text-secondary mb-5\">Participation Models</h3>\n<!-- /wp:heading -->\n<!-- wp:list {\"className\":\"space-y-4 text-on-secondary-container leading-relaxed\"} -->\n<ul class=\"wp-block-list space-y-4 text-on-secondary-container leading-relaxed\"><!-- wp:list-item -->\n<li><strong>Residents:</strong> people who live long term in the tiny houses.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li><strong>Guests:</strong> people who join us weekly or monthly, and stay either in their own accommodation, or in the accommodations that are being offered.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li><strong>Day Visitors:</strong> locals or nearby travellers can opt to join specific workshops or events within The Campus.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li><strong>Earn your stay:</strong> visitors and residents can reduce fees by teaching classes or helping out with jobs within the project. We also offer artist residencies for people who want to teach, build or help out in meaningful ways.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"className\":\"bg-surface-container rounded-2xl p-8 md:p-10 border border-outline-variant/20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-2xl p-8 md:p-10 border border-outline-variant/20\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-3xl md:text-4xl font-headline text-primary mb-5\"} -->\n<h3 class=\"wp-block-heading text-3xl md:text-4xl font-headline text-primary mb-5\">Emphasis on Portuguese Arts and Crafts</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant text-lg leading-relaxed mb-0\"} -->\n<p class=\"text-on-surface-variant text-lg leading-relaxed mb-0\">Portugal has a lot to teach, and we intend to place great emphasis on hosting workshops in traditional Portuguese arts and crafts, such as azulejo painting, cork crafts, ceramics, basket weaving, embroidery, wood carving, textile weaving, cheese and olive oil making and more.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-24 px-6 md:px-12 max-w-[1236px] mx-auto box-border\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-24 px-6 md:px-12 max-w-[1236px] mx-auto box-border\">\n<!-- wp:group {\"className\":\"text-center mb-16\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group text-center mb-16\"><!-- wp:heading {\"level\":2,\"className\":\"text-5xl font-headline text-on-surface mb-6\"} -->\n<h2 class=\"wp-block-heading text-5xl font-headline text-on-surface mb-6\">Got a skill to share? Get in touch with us!</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-on-surface-variant max-w-2xl mx-auto text-lg mb-0\"} -->\n<p class=\"text-on-surface-variant max-w-2xl mx-auto text-lg mb-0\">Please send us an introduction about yourself, your skills and credentials, what you\'d like to offer us and anything else that\'s relevant.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"190\" html_class=\"vila-cf7 vila-cf7--campus\"]\n<!-- /wp:shortcode -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','The Campus','','inherit','closed','closed','','17-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',17,'https://bisque-elk-240168.hostingersite.com/?p=251',0,'revision','',0),
(252,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 py-12 md:py-0 mb-32 max-w-[1236px] mx-auto box-border\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 py-12 md:py-0 mb-32 max-w-[1236px] mx-auto box-border\">\n<!-- wp:columns {\"className\":\"items-center\",\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}}} -->\n<div class=\"wp-block-columns items-center\">\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"z-10\"} -->\n<div class=\"wp-block-column z-10\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":1,\"className\":\"font-barrio text-6xl md:text-8xl text-primary mb-8 leading-none -rotate-2 origin-left\"} -->\n<h1 class=\"wp-block-heading font-barrio text-6xl md:text-8xl text-primary mb-8 leading-none -rotate-2 origin-left\">It takes a village..</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline italic text-2xl md:text-3xl text-on-surface-variant max-w-xl leading-relaxed\"} -->\n<p class=\"font-headline italic text-2xl md:text-3xl text-on-surface-variant max-w-xl leading-relaxed\">\"It takes a village to raise a child\". We sure heard that one before, and we believe this to be very true. So we decided to build that village for our children.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative mt-12 lg:mt-0\"} -->\n<div class=\"wp-block-column relative mt-12 lg:mt-0\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"rounded-xl overflow-hidden aspect-[4/5] shadow-2xl rotate-3\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group rounded-xl overflow-hidden aspect-[4/5] shadow-2xl rotate-3\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill w-full h-full\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill w-full h-full\"><img src=\"/wp-content/uploads/2026/05/kids-hero.jpg\" alt=\"Children in linen clothes playing among ancient cork oak trees in dappled sunlight\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"bg-surface-container-low py-20 md:py-24 rounded-xl mx-4 md:mx-8 mb-28\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group bg-surface-container-low py-20 md:py-24 rounded-xl mx-4 md:mx-8 mb-28\">\n<!-- wp:group {\"className\":\"max-w-7xl mx-auto px-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-7xl mx-auto px-6\">\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"3rem\"}},\"className\":\"items-start\"} -->\n<div class=\"wp-block-columns items-start\">\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"order-2 lg:order-1\"} -->\n<div class=\"wp-block-column order-2 lg:order-1\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"p-3 rounded-xl shadow-sm -rotate-2\",\"layout\":{\"type\":\"default\"},\"style\":{\"color\":{\"background\":\"#faf0df\"}}} -->\n<div class=\"wp-block-group p-3 rounded-xl shadow-sm -rotate-2\" style=\"background-color:#faf0df\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill w-full h-[380px] md:h-[460px] rounded-lg\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill w-full h-[380px] md:h-[460px] rounded-lg\"><img src=\"/wp-content/uploads/2026/05/kids-school.jpg\" alt=\"Group of diverse children and parents sitting in a circle on woven rugs under a large tree, learning together\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"order-1 lg:order-2 space-y-6\"} -->\n<div class=\"wp-block-column order-1 lg:order-2 space-y-6\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-3xl md:text-4xl\"} -->\n<h2 class=\"wp-block-heading font-headline text-3xl md:text-4xl\"><strong>Arete</strong>: The Homeschooling Collective &amp; Activities <span class=\"text-primary\">Ages 5 to 13</span></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-base md:text-lg text-on-surface leading-relaxed italic\"} -->\n<p class=\"font-body text-base md:text-lg text-on-surface leading-relaxed italic\">Arete (noun): the pursuit of excellence through living fully in one\'s potential - of body, mind, and character.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-body text-base md:text-lg text-on-surface leading-relaxed\"} -->\n<p class=\"font-body text-base md:text-lg text-on-surface leading-relaxed\">We are a homeschooling family, and so are most of the families joining and visiting our project. Central to our kids\' busy days is the homeschooling collective, where our kids study together with support of the parents and a homeschooling tutor.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-body text-base md:text-lg text-on-surface leading-relaxed\"} -->\n<p class=\"font-body text-base md:text-lg text-on-surface leading-relaxed\">A big part of our project - and our lives - revolves around the kids, their education, development, health and creating their own thriving kid-community. We take great care to find the right balance between freedom and structure, play and studies, spontaneity and responsibility. We believe that somewhere in that balance, we raise happy, healthy, adaptable and resilient kids.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-body text-base md:text-lg text-on-surface leading-relaxed\"} -->\n<p class=\"font-body text-base md:text-lg text-on-surface leading-relaxed\">Within the project we aim to create a place where our kids learn all about how to be a beautiful human in this world, where they make lifelong friendships and where we give them all the opportunities to find a passion, trade or art that will carry them through a life of inspiration and fulfilment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-body text-base md:text-lg text-on-surface leading-relaxed\"} -->\n<p class=\"font-body text-base md:text-lg text-on-surface leading-relaxed\">As we\'re currently looking for our homeschooling tutor, important elements of the structure surrounding our collective will still be decided. But to give you an idea, we are aiming for something along the following lines:</p>\n<!-- /wp:paragraph -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"1rem\"}},\"className\":\"pt-1\"} -->\n<div class=\"wp-block-columns pt-1\">\n<!-- wp:column {\"className\":\"bg-surface/70 border border-outline-variant/25 rounded-xl p-5\"} -->\n<div class=\"wp-block-column bg-surface/70 border border-outline-variant/25 rounded-xl p-5\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-xl text-primary mb-2\"} -->\n<h3 class=\"wp-block-heading font-headline text-xl text-primary mb-2\">Homeschooling Hub</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm md:text-base text-on-surface-variant leading-relaxed mb-0\"} -->\n<p class=\"text-sm md:text-base text-on-surface-variant leading-relaxed mb-0\">2 hours a day of dedicated (home)schoolwork supported by our tutor, in small classes of similar ages, following the curriculum chosen by the parents.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"bg-surface/70 border border-outline-variant/25 rounded-xl p-5\"} -->\n<div class=\"wp-block-column bg-surface/70 border border-outline-variant/25 rounded-xl p-5\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-xl text-primary mb-2\"} -->\n<h3 class=\"wp-block-heading font-headline text-xl text-primary mb-2\">Extracurricular Activities</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-sm md:text-base text-on-surface-variant leading-relaxed mb-0\"} -->\n<p class=\"text-sm md:text-base text-on-surface-variant leading-relaxed mb-0\">Approximately 4 hours a day of structured play through activities, workshops and classes teaching skills in all fields of life.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"px-6 md:px-12 lg:px-24 mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group px-6 md:px-12 lg:px-24 mb-32\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl text-primary text-center mb-20\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl text-primary text-center mb-20\">Daily Extracurricular Activities</h2>\n<!-- /wp:heading -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}}} -->\n<div class=\"wp-block-columns\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 flex flex-col justify-between h-full hover:bg-surface-bright transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 flex flex-col justify-between h-full hover:bg-surface-bright transition-colors duration-500\">\n<!-- wp:group {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"className\":\"mb-8\"} -->\n<p class=\"mb-8\"><span class=\"w-16 h-16 bg-primary-container rounded-full flex items-center justify-center inline-flex\"><span class=\"material-symbols-outlined text-on-primary-container text-3xl\" aria-hidden=\"true\">school</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-primary mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-primary mb-4\">Creative Arts &amp; Knowledge</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg opacity-80 mb-8\"} -->\n<p class=\"font-headline text-lg opacity-80 mb-8\">Ceramics, woodwork, natural building, weaving, photography, improv, painting, writing, music, sustainability workshops, languages, cooperative living and conflict resolution skills.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill aspect-video rounded-lg overflow-hidden\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill aspect-video rounded-lg overflow-hidden\"><img src=\"/wp-content/uploads/2026/05/kids-creative.jpg\" alt=\"Hands of a child working with wet clay on a pottery wheel\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"md:translate-y-12\"} -->\n<div class=\"wp-block-column md:translate-y-12\">\n<!-- wp:group {\"className\":\"bg-secondary-container/30 rounded-xl p-8 flex flex-col justify-between h-full hover:bg-secondary-container transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-secondary-container/30 rounded-xl p-8 flex flex-col justify-between h-full hover:bg-secondary-container transition-colors duration-500\">\n<!-- wp:group {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"className\":\"mb-8\"} -->\n<p class=\"mb-8\"><span class=\"w-16 h-16 bg-secondary-container rounded-full flex items-center justify-center inline-flex\"><span class=\"material-symbols-outlined text-secondary text-3xl\" aria-hidden=\"true\">sports_gymnastics</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-secondary mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-secondary mb-4\">Movement and Stillness</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg opacity-80 mb-8\"} -->\n<p class=\"font-headline text-lg opacity-80 mb-8\">Climbing, dance, trail running, archery, martial arts, horseback riding, swimming, fencing, table tennis, yoga, tai-chi, breathwork, meditation and mindfulness.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill aspect-video rounded-lg overflow-hidden\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill aspect-video rounded-lg overflow-hidden\"><img src=\"/wp-content/uploads/2026/05/kids-movement.jpg\" alt=\"Sunlight streaming through tall forest trees\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-tertiary-container/30 rounded-xl p-8 flex flex-col justify-between h-full hover:bg-tertiary-container transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-tertiary-container/30 rounded-xl p-8 flex flex-col justify-between h-full hover:bg-tertiary-container transition-colors duration-500\">\n<!-- wp:group {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"className\":\"mb-8\"} -->\n<p class=\"mb-8\"><span class=\"w-16 h-16 bg-tertiary-container rounded-full flex items-center justify-center inline-flex\"><span class=\"material-symbols-outlined text-on-tertiary-container text-3xl\" aria-hidden=\"true\">handyman</span></span></p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-2xl text-tertiary mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-2xl text-tertiary mb-4\">Practical Skills</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg opacity-80 mb-8\"} -->\n<p class=\"font-headline text-lg opacity-80 mb-8\">Permaculture, cooking, fermentation, foraging, animal care, herbal medicine, survival skills, first aid, beekeeping, composting, construction, carpentry, welding and sewing.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill aspect-video rounded-lg overflow-hidden\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill aspect-video rounded-lg overflow-hidden\"><img src=\"/wp-content/uploads/2026/05/kids-practical.jpg\" alt=\"Assortment of fresh vegetables on a rustic wooden table\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative py-32 overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative py-32 overflow-hidden\">\n<!-- wp:html -->\n<div class=\"absolute inset-0 bg-primary/5 -skew-y-3 scale-110 pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"max-w-4xl mx-auto px-6 relative text-center\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-4xl mx-auto px-6 relative text-center\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl md:text-7xl mb-12\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl md:text-7xl mb-12\">The Coddiwomples<br><span class=\"text-primary\">Ages 0 to 5</span></h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl md:text-3xl italic text-on-surface leading-snug mb-12\"} -->\n<p class=\"font-headline text-2xl md:text-3xl italic text-on-surface leading-snug mb-12\">Coddiwomple (verb): To travel in a purposeful manner towards a vague destination.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl md:text-3xl text-on-surface leading-snug\"} -->\n<p class=\"font-headline text-2xl md:text-3xl text-on-surface leading-snug\">For the littlest ones we also have loads to do! Join the Coddiwomples; with drop-in classes and activities -mostly outdoor- throughout the day. We also have on-site babysitters, available for private babysitting at most hours of the day.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"px-6 md:px-12 lg:px-24 py-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group px-6 md:px-12 lg:px-24 py-32\">\n<!-- wp:group {\"className\":\"bg-surface-container-highest rounded-[3rem] p-12 md:p-24 overflow-hidden relative max-w-[1300px] mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container-highest rounded-[3rem] p-12 md:p-24 overflow-hidden relative max-w-[1300px] mx-auto\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill absolute top-0 right-0 w-2/5 h-full opacity-50 hidden lg:block\"} -->\n<figure class=\"wp-block-image size-full vila-img-fill absolute top-0 right-0 w-2/5 h-full opacity-50 hidden lg:block\"><img src=\"/wp-content/uploads/2026/05/kids-contact.jpg\" alt=\"Wide shot of the Alentejo cork forest at dusk with a soft purple sky\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"relative z-10 max-w-xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative z-10 max-w-xl\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl md:text-6xl text-on-background mb-8 leading-tight\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl md:text-6xl text-on-background mb-8 leading-tight\">Want to know more?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-xl mb-12 opacity-90\"} -->\n<p class=\"font-headline text-xl mb-12 opacity-90\">Get in touch with us for all your questions and suggestions regarding our kids program, and to book your dates.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"},\"style\":{\"spacing\":{\"blockGap\":\"1.5rem\"}}} -->\n<div class=\"wp-block-buttons\">\n<!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button bg-primary text-on-primary px-10 py-5 rounded-full font-label font-bold text-lg shadow-lg hover:scale-105 transition-transform\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Contact us</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n','The Kids','','inherit','closed','closed','','18-revision-v1','','','2026-05-06 12:09:18','2026-05-06 12:09:18','',18,'https://bisque-elk-240168.hostingersite.com/?p=252',0,'revision','',0),
(253,0,'2026-05-06 12:09:18','2026-05-06 12:09:18','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner pt-0 pb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 pb-20\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] max-w-[1236px] mx-auto box-border px-8 grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] max-w-[1236px] mx-auto box-border px-8 grid grid-cols-1 lg:grid-cols-12 gap-12 items-center content-center\">\n<!-- wp:group {\"className\":\"lg:col-span-5 z-10\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-5 z-10\">\n<!-- wp:paragraph {\"className\":\"font-label text-primary tracking-[0.2em] uppercase text-sm mb-4\"} -->\n<p class=\"font-label text-primary tracking-[0.2em] uppercase text-sm mb-4\">Get in Touch</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":1,\"className\":\"font-headline text-6xl md:text-8xl text-on-surface leading-tight mb-8\"} -->\n<h1 class=\"wp-block-heading font-headline text-6xl md:text-8xl text-on-surface leading-tight mb-8\">It\'s nice to meet you here!</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-xl text-on-surface-variant max-w-md leading-relaxed mb-12\"} -->\n<p class=\"font-body text-xl text-on-surface-variant max-w-md leading-relaxed mb-12\">Thanks for wanting to get in touch with us. We\'re excited to learn more about you, and the people and creatures that belong with you.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"lg:col-span-7 relative\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group lg:col-span-7 relative\">\n<!-- wp:group {\"className\":\"rounded-xl overflow-hidden aspect-[4/5] md:aspect-[16/10] shadow-2xl\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group rounded-xl overflow-hidden aspect-[4/5] md:aspect-[16/10] shadow-2xl\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill w-full h-full\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill w-full h-full\"><img src=\"/wp-content/uploads/2026/05/contact-hero.jpg\" alt=\"Scenic Alentejo landscape\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n<!-- wp:group {\"className\":\"absolute -bottom-10 -left-10 md:left-20 bg-surface-container-lowest/90 backdrop-blur-xl p-10 rounded-lg shadow-xl max-w-sm hidden md:block\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute -bottom-10 -left-10 md:left-20 bg-surface-container-lowest/90 backdrop-blur-xl p-10 rounded-lg shadow-xl max-w-sm hidden md:block\">\n<!-- wp:group {\"className\":\"flex items-start gap-4\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group flex items-start gap-4\">\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><span class=\"material-symbols-outlined text-primary text-3xl\" aria-hidden=\"true\">favorite</span></p>\n<!-- /wp:paragraph -->\n<!-- wp:group {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\">\n<!-- wp:paragraph {\"className\":\"font-label text-xs uppercase tracking-widest text-secondary mb-1\"} -->\n<p class=\"font-label text-xs uppercase tracking-widest text-secondary mb-1\">With love</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"font-headline text-lg italic mb-0\"} -->\n<p class=\"font-headline text-lg italic mb-0\">Sammy, Hans, Joyaa and Akhoda</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"max-w-[1236px] mx-auto box-border px-8 mt-40\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group max-w-[1236px] mx-auto box-border px-8 mt-40