(282,0,'2026-05-07 09:07:14','2026-05-07 09:07:14','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-home\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-home\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative w-full max-w-[1236px] mx-auto box-border px-8 pt-8 pb-10 mb-28 md:mb-32\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative w-full max-w-[1236px] mx-auto box-border px-8 pt-8 pb-10 mb-28 md:mb-32\">\n<!-- wp:group {\"className\":\"relative w-full rounded-xl overflow-hidden editorial-shadow md:min-h-[calc(100vh-140px)]\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative w-full rounded-xl overflow-hidden editorial-shadow md:min-h-[calc(100vh-140px)]\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill vila-home-hero-image w-full aspect-[4/3] md:absolute md:inset-0 md:h-full md:min-h-0 md:w-full md:aspect-auto\"} -->\n<figure class=\"wp-block-image size-full vila-img-fill vila-home-hero-image w-full aspect-[4/3] md:absolute md:inset-0 md:h-full md:min-h-0 md:w-full md:aspect-auto\"><img src=\"/wp-content/uploads/2026/05/home-hero-scaled.jpg\" alt=\"Vila Akoya home hero\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"relative flex flex-col justify-end bg-gradient-to-b from-surface-container/80 via-surface-container/95 to-surface-container p-6 sm:p-8 md:absolute md:inset-0 md:justify-center md:bg-gradient-to-t md:from-on-surface/35 md:via-on-surface/15 md:to-transparent md:p-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative flex flex-col justify-end bg-gradient-to-b from-surface-container/80 via-surface-container/95 to-surface-container p-6 sm:p-8 md:absolute md:inset-0 md:justify-center md:bg-gradient-to-t md:from-on-surface/35 md:via-on-surface/15 md:to-transparent md:p-20\">\n<!-- wp:group {\"className\":\"max-w-4xl space-y-6 md:text-on-primary\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-4xl space-y-6 md:text-on-primary\">\n<!-- wp:heading {\"level\":1,\"className\":\"text-5xl md:text-8xl font-barrio text-on-surface md:text-on-primary leading-tight\"} -->\n<h1 class=\"wp-block-heading text-5xl md:text-8xl font-barrio text-on-surface md:text-on-primary leading-tight\">The little village of our dreams</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-2xl text-on-surface-variant md:text-on-primary/90 font-light max-w-2xl leading-relaxed\"} -->\n<p class=\"text-lg md:text-2xl text-on-surface-variant md:text-on-primary/90 font-light max-w-2xl leading-relaxed\">A tiny house village, glamping and creative community bordering the river Mira in the south of Alentejo. An extraordinary place of creation, relaxation and inspiration that we get to share with our friends and friends disguised as strangers.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"className\":\"flex flex-wrap gap-4 pt-4\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons flex flex-wrap gap-4 pt-4\">\n<!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button px-8 py-4 bg-gradient-to-r from-primary to-primary-container text-on-primary rounded-xl font-medium text-lg hover:scale-95 transition-transform\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your stay</a></div>\n<!-- /wp:button -->\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button px-8 py-4 bg-primary/10 border border-primary/20 text-primary md:bg-surface-bright/20 md:border-white/20 md:text-on-primary rounded-xl font-medium text-lg hover:bg-primary/15 md:hover:bg-surface-bright/30 transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/campus/\">Tell me more!</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"mb-32 md:mb-40\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group mb-32 md:mb-40\">\n<!-- wp:columns {\"className\":\"min-h-[min(100vh,70rem)] md:min-h-[calc(100vh-6rem)] gap-0 vila-split-flush\"} -->\n<div class=\"wp-block-columns min-h-[min(100vh,70rem)] md:min-h-[calc(100vh-6rem)] gap-0 vila-split-flush\">\n<!-- wp:column {\"className\":\"relative group flex flex-col items-center p-10 md:p-20 lg:p-24 bg-surface-container-low transition-all duration-700 hover:bg-surface-container overflow-hidden\"} -->\n<div class=\"wp-block-column relative group flex flex-col items-center p-10 md:p-20 lg:p-24 bg-surface-container-low transition-all duration-700 hover:bg-surface-container overflow-hidden\">\n<!-- wp:html -->\n<div class=\"absolute -top-10 -left-10 w-64 h-64 bg-tertiary/5 rounded-full blur-3xl group-hover:bg-tertiary/10 transition-colors pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\",\"layout\":{\"type\":\"default\"},\"style\":{\"spacing\":{\"blockGap\":\"1.75rem\"}}} -->\n<div class=\"wp-block-group z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\">\n<!-- wp:paragraph {\"className\":\"text-tertiary text-2xl font-headline\"} -->\n<p class=\"text-tertiary text-2xl font-headline\">A place to stay</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":2,\"className\":\"text-6xl md:text-7xl font-barrio text-on-surface narrow-header\"} -->\n<h2 class=\"wp-block-heading text-6xl md:text-7xl font-barrio text-on-surface narrow-header\">The Village</h2>\n<!-- /wp:heading -->\n<!-- wp:separator {\"className\":\"h-1 w-24 bg-tertiary/20 mx-auto rounded-full border-0\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity h-1 w-24 bg-tertiary/20 mx-auto rounded-full border-0\"/>\n<!-- /wp:separator -->\n<!-- wp:paragraph {\"className\":\"text-xl font-light text-on-surface-variant italic\"} -->\n<p class=\"text-xl font-light text-on-surface-variant italic\">Unique tiny homes in all shapes and forms. A feast for the eye and a home for the kind. This is the little village we\'ve always been hoping to find.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill vila-home-village-image w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill vila-home-village-image w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6\"><img src=\"/wp-content/uploads/2026/05/village-small.jpg\" alt=\"The Village\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"pt-6\"} -->\n<p class=\"pt-6\"><a class=\"font-headline font-bold text-lg text-tertiary-dim underline decoration-tertiary/40 underline-offset-8 hover:decoration-tertiary transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/village/\">Looking for a village?</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"relative group flex flex-col justify-center items-center p-10 md:p-20 lg:p-24 bg-secondary-container/30 transition-all duration-700 hover:bg-secondary-container/50 overflow-hidden\"} -->\n<div class=\"wp-block-column relative group flex flex-col justify-center items-center p-10 md:p-20 lg:p-24 bg-secondary-container/30 transition-all duration-700 hover:bg-secondary-container/50 overflow-hidden\">\n<!-- wp:html -->\n<div class=\"absolute -bottom-10 -right-10 w-64 h-64 bg-secondary/5 rounded-full blur-3xl group-hover:bg-secondary/10 transition-colors pointer-events-none\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\",\"layout\":{\"type\":\"default\"},\"style\":{\"spacing\":{\"blockGap\":\"1.75rem\"}}} -->\n<div class=\"wp-block-group z-10 text-center space-y-7 md:space-y-8 max-w-[31rem] mx-auto\">\n<!-- wp:paragraph {\"className\":\"text-secondary text-2xl font-headline\"} -->\n<p class=\"text-secondary text-2xl font-headline\">...or to visit</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading {\"level\":2,\"className\":\"text-6xl md:text-7xl font-barrio text-on-surface narrow-header\"} -->\n<h2 class=\"wp-block-heading text-6xl md:text-7xl font-barrio text-on-surface narrow-header\">The Campsite</h2>\n<!-- /wp:heading -->\n<!-- wp:separator {\"className\":\"h-1 w-24 bg-secondary/20 mx-auto rounded-full border-0\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity h-1 w-24 bg-secondary/20 mx-auto rounded-full border-0\"/>\n<!-- /wp:separator -->\n<!-- wp:paragraph {\"className\":\"text-xl font-light text-on-surface-variant italic\"} -->\n<p class=\"text-xl font-light text-on-surface-variant italic\">Want to dip you toe in our home-away-from home? Swing by, join our table, have a swim, build a treehouse, make a friend.. and leave forever changed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill vila-home-campsite-image w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill vila-home-campsite-image w-full aspect-[4/3] overflow-hidden rounded-2xl editorial-shadow mb-6\"><img src=\"/wp-content/uploads/2026/05/campsite.jpeg\" alt=\"The Campsite\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"pt-6\"} -->\n<p class=\"pt-6\"><a class=\"font-headline font-bold text-lg text-secondary-dim underline decoration-secondary/40 underline-offset-8 hover:decoration-secondary transition-all\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Book your dates</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"max-w-[1236px] mx-auto box-border px-8 mb-32 md:mb-40\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group max-w-[1236px] mx-auto box-border px-8 mb-32 md:mb-40\">\n<!-- wp:columns {\"className\":\"gap-12 lg:gap-20 items-stretch vila-columns-stretch\"} -->\n<div class=\"wp-block-columns gap-12 lg:gap-20 items-stretch vila-columns-stretch\">\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"md:col-span-5 relative flex flex-col h-full min-h-0\"} -->\n<div class=\"wp-block-column md:col-span-5 relative flex flex-col h-full min-h-0\" style=\"flex-basis:41.66%\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill flex-1 w-full min-h-[min(26rem,55vh)] md:min-h-[min(32rem,72vh)] overflow-hidden rounded-[2.5rem] md:rounded-[3rem] editorial-shadow relative z-10 rotate-[-1.5deg]\"} -->\n<figure class=\"wp-block-image size-large vila-img-fill flex-1 w-full min-h-[min(26rem,55vh)] md:min-h-[min(32rem,72vh)] overflow-hidden rounded-[2.5rem] md:rounded-[3rem] editorial-shadow relative z-10 rotate-[-1.5deg]\"><img src=\"/wp-content/uploads/2026/05/river.jpeg\" alt=\"River Mira\"/></figure>\n<!-- /wp:image -->\n<!-- wp:group {\"className\":\"absolute bottom-[-2rem] right-[-2rem] glass-card bg-surface-bright/80 p-6 rounded-2xl editorial-shadow max-w-[200px] z-20 rotate-[3deg] hidden md:block\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group absolute bottom-[-2rem] right-[-2rem] glass-card bg-surface-bright/80 p-6 rounded-2xl editorial-shadow max-w-[200px] z-20 rotate-[3deg] hidden md:block\">\n<!-- wp:paragraph {\"className\":\"text-sm leading-tight text-on-surface flex flex-col gap-2\"} -->\n<p class=\"text-sm leading-tight text-on-surface flex flex-col gap-2\"><span class=\"material-symbols-outlined text-primary text-4xl mb-2\" style=\"font-variation-settings:\'FILL\' 1\" aria-hidden=\"true\">favorite</span>A little village with a big heart.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"58.33%\",\"className\":\"md:col-span-7 space-y-8 flex flex-col justify-center\"} -->\n<div class=\"wp-block-column md:col-span-7 space-y-8 flex flex-col justify-center\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":3,\"className\":\"text-4xl md:text-6xl font-headline text-on-surface font-light leading-tight\"} -->\n<h3 class=\"wp-block-heading text-4xl md:text-6xl font-headline text-on-surface font-light leading-tight\">That little village <br><span class=\"text-primary italic\">we\'ve been looking for</span></h3>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"space-y-6 text-xl font-light text-on-surface-variant leading-relaxed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6 text-xl font-light text-on-surface-variant leading-relaxed\">\n<!-- wp:paragraph -->\n<p>We wanted to live in the forest, and raise our kids amongst the trees. But we did not want to do it alone. Frankly, we\'re done with doing everything alone! Who came up with that? Lucky for us, there are loads more people like us. So we got a bunch of fantastic humans together and set out to build the little village of our dreams.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Expect to find something fantastic in every corner of this space. With playgrounds for children and for grown-ups, areas for wellness and relaxation, spaces designed for connection, creation and celebration, and a full agenda of workshops, classes and activities for humans of all ages.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\":\"pt-4\"} -->\n<p class=\"pt-4\"><a class=\"group flex items-center gap-4 text-primary font-bold text-xl\" href=\"https://bisque-elk-240168.hostingersite.com/campus/\">Learn more about the activities for adults and kids<span class=\"material-symbols-outlined group-hover:translate-x-2 transition-transform\" aria-hidden=\"true\">arrow_right_alt</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"relative mb-32 md:mb-40 overflow-x-hidden bg-gradient-to-b from-[#ebe4d4] via-[#e8dcc8] to-[#e5d6c4] text-[#3d2a22]\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group relative mb-32 md:mb-40 overflow-x-hidden bg-gradient-to-b from-[#ebe4d4] via-[#e8dcc8] to-[#e5d6c4] text-[#3d2a22]\">\n<!-- wp:html -->\n<div class=\"absolute inset-0 pointer-events-none opacity-[0.35] bg-[radial-gradient(ellipse_at_30%_20%,rgba(154,63,33,0.08),transparent_50%),radial-gradient(ellipse_at_70%_80%,rgba(92,99,72,0.06),transparent_45%)]\" aria-hidden=\"true\"></div>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"relative max-w-[1236px] mx-auto box-border px-8 py-20 md:py-28\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative max-w-[1236px] mx-auto box-border px-8 py-20 md:py-28\">\n<!-- wp:group {\"tagName\":\"header\",\"className\":\"text-center max-w-3xl mx-auto mb-14 md:mb-20 space-y-4\",\"layout\":{\"type\":\"default\"}} -->\n<header class=\"wp-block-group text-center max-w-3xl mx-auto mb-14 md:mb-20 space-y-4\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-barrio text-5xl md:text-7xl text-on-surface leading-tight\"} -->\n<h2 class=\"wp-block-heading font-barrio text-5xl md:text-7xl text-on-surface leading-tight\">Who are we?</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-tertiary text-xl md:text-2xl tracking-wide\"} -->\n<p class=\"font-headline text-tertiary text-xl md:text-2xl tracking-wide\">The family behind Vila Akoya</p>\n<!-- /wp:paragraph -->\n<!-- wp:separator {\"className\":\"h-px w-32 bg-tertiary/25 mx-auto rounded-full border-0\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity h-px w-32 bg-tertiary/25 mx-auto rounded-full border-0\"/>\n<!-- /wp:separator -->\n</header>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\">\n<!-- wp:column {\"className\":\"order-2 md:order-1 space-y-6\"} -->\n<div class=\"wp-block-column order-2 md:order-1 space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Joyaa</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">It takes a village to raise a child, and for us it took a child to build a village. Vila Akoya wouldn\'t be anything without our daughter Joyaa. It\'s with her in mind that we envision the village in which we want to raise her; a green and inspiring place with a vibrant community where she - and her brother - will get to grow, learn and adventure.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Joyaa is 10 years old now. She\'s creative, funny, kind, smart and a great friend to have… and did I mention she\'s creative?</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Joyaa spends her days building castles for beetles with leaves and sticks that she finds, while singing songs about the things that she sees on her way, and what she thinks about them.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Joyaa is the artiste in our family, she loves reading, drawing, making music and climbing trees; she carries a big smile and an even bigger heart. You\'ll feel it when you meet her - this little lady is someone special.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-1 md:order-2 flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column order-1 md:order-2 flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/joyaa.jpg\" alt=\"Joyaa smiling with a large autumn leaf\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\">\n<!-- wp:column {\"className\":\"order-2 md:order-1 space-y-6\"} -->\n<div class=\"wp-block-column order-2 md:order-1 space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Sammy</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">My name is Sammy. I am Joyaa and Akhoda\'s mother and Hans\'s partner.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Besides a mother and partner, I am many other things. I have an entrepreneurial mind and a heart for sustainability; I founded and ran sustainable clothing and baby brands, and spend the last 4 years working on Vila Akoya. Just like Joyaa I am creative, love making music, learning new things and like to work with my hands.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">I spent most of my adult life travelling the world, had Joyaa along the way, and about 6 years ago Hans joined us — or we him! Together we decided to settle down in Portugal to build our dream: Vila Akoya.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Hans said I should call myself the heart and soul of the project, and I will do so with a humble pride. I have a clear vision of the village we wish to build for our children and ourselves. A vision that I am grateful to get to share with so many others.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-1 md:order-2 flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column order-1 md:order-2 flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--blob-3 w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--blob-3 w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/sammy.jpg\" alt=\"Sammy and Joyaa smiling together outdoors\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-16 md:mb-24 lg:mb-32\">\n<!-- wp:column {\"className\":\"flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--blob-2 w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--blob-2 w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/hans.jpg\" alt=\"Hans smiling with Joyaa leaning on his shoulder\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"space-y-6\"} -->\n<div class=\"wp-block-column space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Hans</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Hans is the <em class=\"text-on-surface\">brains</em> and the <em class=\"text-on-surface\">muscles</em> behind Vila Akoya. He knows and learns about the possibles and impossibles surrounding our projects. He always finds answers to the difficult questions, and he does so by tirelessly reading through piles of documents, underlining all that\'s relevant and questioning all that can be questioned, then puts on his gloves and starts lifting whatever heavy needs lifting before brushing off his shirt to sit patiently with Joyaa working on her homework, or playing tirelessly with little Akhoda.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">Hans has spent the last 8 years working in real estate. Before that he was a national champion fencer and fencing coach in Canada, ran an organic farm, holds a degree in Cognitive Science and Philosophy and studied and taught an Indian martial art called Kalaripayattu — pretty impressive, right?</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-10 md:gap-16 lg:gap-20 items-center mb-12 md:mb-20 lg:mb-24\"} -->\n<div class=\"wp-block-columns gap-10 md:gap-16 lg:gap-20 items-center mb-12 md:mb-20 lg:mb-24\">\n<!-- wp:column {\"className\":\"order-1 flex w-full justify-center items-center\"} -->\n<div class=\"wp-block-column order-1 flex w-full justify-center items-center\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--blob-4 w-full\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--blob-4 w-full\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/akhoda.jpg\" alt=\"Hans holding baby Akhoda\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"className\":\"order-2 space-y-6\"} -->\n<div class=\"wp-block-column order-2 space-y-6\">\n<!-- wp:heading {\"level\":3,\"className\":\"font-barrio text-3xl md:text-4xl text-on-surface\"} -->\n<h3 class=\"wp-block-heading font-barrio text-2xl md:text-3xl text-on-surface\">Little Akhoda</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">In summer 2024 this little guy made our family complete. Akhoda is such a wonderful little person; he is strong but kind, he loves his family and the forest and meets plants and creatures with gentle hands and great curiosity.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph {\"className\":\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\"} -->\n<p class=\"text-lg md:text-xl font-light leading-relaxed text-on-surface-variant\">For us he is a big inspiration to want to be our best selves — so that when he looks his big eyes up at us, he sees good people who work hard doing something beautiful and meaningful in the world. This project is exactly that, for us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"className\":\"max-w-4xl mx-auto text-center space-y-8\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-4xl mx-auto text-center space-y-8\">\n<!-- wp:group {\"className\":\"who-we-portrait who-we-portrait--wide w-full mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait who-we-portrait--wide w-full mx-auto\">\n<!-- wp:html -->\n<span class=\"who-we-portrait__aura\" aria-hidden=\"true\"></span>\n<!-- /wp:html -->\n<!-- wp:group {\"className\":\"who-we-portrait__clip\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group who-we-portrait__clip\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"/wp-content/uploads/2026/05/family.jpg\" alt=\"The family together in the forest in front of a large tree\" loading=\"lazy\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n<!-- wp:paragraph {\"className\":\"font-headline text-xl text-tertiary-dim italic\"} -->\n<p class=\"font-headline text-xl text-tertiary-dim italic\">More about us and the people around us, our story and what brought us here.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p><a class=\"inline-flex items-center gap-2 text-primary font-bold text-lg hover:underline underline-offset-4\" href=\"https://bisque-elk-240168.hostingersite.com/about/\">How we got here<span class=\"material-symbols-outlined text-xl\" aria-hidden=\"true\">arrow_forward</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"full\",\"className\":\"va-home-digi-family max-w-screen-xl mx-auto px-6 sm:px-8 mb-32 md:mb-40 editorial-shadow rounded-[2rem] md:rounded-[3rem] overflow-hidden items-stretch vila-columns-stretch gap-0 vila-split-flush md:min-h-[min(28rem,70vh)]\"} -->\n<div class=\"wp-block-columns alignfull va-home-digi-family max-w-screen-xl mx-auto px-6 sm:px-8 mb-32 md:mb-40 editorial-shadow rounded-[2rem] md:rounded-[3rem] overflow-hidden items-stretch vila-columns-stretch gap-0 vila-split-flush md:min-h-[min(28rem,70vh)]\">\n<!-- wp:column {\"width\":\"66.66%\",\"className\":\"bg-primary text-on-primary p-10 md:p-14 lg:p-16 flex flex-col justify-center min-h-0 space-y-6\"} -->\n<div class=\"wp-block-column bg-primary text-on-primary p-10 md:p-14 lg:p-16 flex flex-col justify-center min-h-0 space-y-6\" style=\"flex-basis:66.66%\">\n<!-- wp:heading {\"level\":2,\"className\":\"text-5xl md:text-7xl font-headline leading-tight\"} -->\n<h2 class=\"wp-block-heading text-5xl md:text-7xl font-headline leading-tight\">Join our digi-family</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl opacity-90 leading-relaxed font-light max-w-2xl\"} -->\n<p class=\"text-xl opacity-90 leading-relaxed font-light max-w-2xl\">Want to stay in the loop about what\'s happening on our little slice of paradise? Enter your email here, and we will try not to spam you too much with the things we are excited to share.</p>\n<!-- /wp:paragraph -->\n<!-- wp:shortcode -->\n[contact-form-7 id=\"276\" html_class=\"vila-cf7 vila-cf7--newsletter\"]\n<!-- /wp:shortcode -->\n<!-- wp:paragraph {\"className\":\"text-sm opacity-85 mt-2\"} -->\n<p class=\"text-sm opacity-85 mt-2\"><a class=\"underline underline-offset-4 hover:opacity-100\" href=\"https://bisque-elk-240168.hostingersite.com/contact/\">Want to get in touch? Find our contact info here</a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"33.33%\",\"className\":\"relative hidden md:block md:h-full bg-primary overflow-hidden min-h-[12rem] md:min-h-0\"} -->\n<div class=\"wp-block-column relative hidden md:block md:h-full bg-primary overflow-hidden min-h-[12rem] md:min-h-0\" style=\"flex-basis:33.33%\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vila-img-fill absolute inset-0 h-full w-full opacity-[0.58] [&>img]:object-center\"} -->\n<figure class=\"wp-block-image size-full vila-img-fill absolute inset-0 h-full w-full opacity-[0.58] [&>img]:object-center\"><img src=\"/wp-content/uploads/2026/05/home-newsletter.jpg\" alt=\"People gathered around a table outdoors at Vila Akoya\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n','Home','','inherit','closed','closed','','12-revision-v1','','','2026-05-07 09:07:14','2026-05-07 09:07:14','',12,'https://bisque-elk-240168.hostingersite.com/?p=282',0,'revision','',0),
(283,0,'2026-05-07 09:07:14','2026-05-07 09:07:14','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner\">\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 mb-20 relative pb-12 md:pb-0 max-w-[1236px] mx-auto box-border\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group min-h-[calc(100vh-6rem)] flex flex-col justify-center px-8 mb-20 relative pb-12 md:pb-0 max-w-[1236px] mx-auto box-border\">\n<!-- wp:columns {\"className\":\"gap-6 items-end md:items-center\"} -->\n<div class=\"wp-block-columns gap-6 items-end md:items-center\">\n<!-- wp:column {\"width\":\"58.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:58.33%\">\n<!-- wp:heading {\"level\":1,\"className\":\"font-barrio text-6xl md:text-8xl text-primary leading-none mb-8 -rotate-1 origin-left\"} -->\n<h1 class=\"wp-block-heading font-barrio text-6xl md:text-8xl text-primary leading-none mb-8 -rotate-1 origin-left\">Our tiny house eco village</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline text-2xl md:text-3xl italic text-tertiary max-w-xl mb-12\"} -->\n<p class=\"font-headline text-2xl md:text-3xl italic text-tertiary max-w-xl mb-12\">A little village of tiny houses and other out-of-the-ordinary living spaces.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"41.66%\",\"className\":\"relative\"} -->\n<div class=\"wp-block-column relative\" style=\"flex-basis:41.66%\">\n<!-- wp:group {\"className\":\"aspect-[4/5] rounded-xl overflow-hidden editorial-shadow\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group aspect-[4/5] rounded-xl overflow-hidden editorial-shadow\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/village-large.jpg\" alt=\"Modern tiny house with wooden cladding nestled in a cork oak forest under warm golden hour light\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"bg-surface-container-low py-32 px-6 md:px-20 overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group bg-surface-container-low py-32 px-6 md:px-20 overflow-hidden\">\n<!-- wp:group {\"className\":\"max-w-7xl mx-auto\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group max-w-7xl mx-auto\">\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":\"5rem\"}},\"className\":\"items-center\"} -->\n<div class=\"wp-block-columns items-center\">\n<!-- wp:column {\"width\":\"50%\",\"className\":\"w-full md:w-1/2 relative\"} -->\n<div class=\"wp-block-column w-full md:w-1/2 relative\" style=\"flex-basis:50%\">\n<!-- wp:group {\"className\":\"relative z-10 aspect-square rounded-full border-[1.5rem] border-surface-container-high overflow-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group relative z-10 aspect-square rounded-full border-[1.5rem] border-surface-container-high overflow-hidden\">\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"w-full h-full object-cover\"} -->\n<figure class=\"wp-block-image size-large w-full h-full object-cover\"><img src=\"/wp-content/uploads/2026/05/village-circle.jpg\" alt=\"Aerial view of rolling Alentejo hills with scattered olive trees\"/></figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column {\"width\":\"50%\",\"className\":\"w-full md:w-1/2\"} -->\n<div class=\"wp-block-column w-full md:w-1/2\" style=\"flex-basis:50%\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl font-bold text-on-surface mb-8\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl font-bold text-on-surface mb-8\">A Tiny Home Away From Home</h2>\n<!-- /wp:heading -->\n<!-- wp:group {\"className\":\"space-y-6 text-xl text-on-surface-variant leading-relaxed\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group space-y-6 text-xl text-on-surface-variant leading-relaxed\">\n<!-- wp:paragraph -->\n<p>One side of our project, which we call \"The Village\" is the more community-like part of our project; a car-free area with about 15 plots intended exclusively for tiny homes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Here a diverse crowd of fantastic humans of all sorts of different backgrounds, cultures and ages, spend longer stretches of time with us in their own tiny homes and other kinds of unique accommodations.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>We want this little village to be an inspiring place, so it is important to us is that these tiny homes are really beautiful, interesting, unique, weird, cute or absolutely fantastic, that they\'re built in a sustainable way and do not have a concrete foundation.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Every now and then we have some plots available for sale or for rent in our little village. If you\'d like to be considered for one of these spots, please get in touch with us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n</div>\n<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n</section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"py-32 px-6 md:px-20\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group py-32 px-6 md:px-20\">\n<!-- wp:group {\"className\":\"text-center mb-20\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group text-center mb-20\">\n<!-- wp:heading {\"level\":2,\"className\":\"font-headline text-5xl text-primary mb-4\"} -->\n<h2 class=\"wp-block-heading font-headline text-5xl text-primary mb-4\">How to join our little village</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-headline italic text-2xl text-tertiary mb-0\"} -->\n<p class=\"font-headline italic text-2xl text-tertiary mb-0\">There are three ways in which to join our tiny house village</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"2rem\"}},\"className\":\"max-w-7xl mx-auto items-stretch vila-columns-stretch\"} -->\n<div class=\"wp-block-columns alignwide max-w-7xl mx-auto items-stretch vila-columns-stretch\">\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full group hover:bg-surface-bright transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full group hover:bg-surface-bright transition-colors duration-500\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 bg-secondary-container rounded-full flex items-center justify-center mb-8 group-hover:scale-110 transition-transform duration-300\"><span class=\"material-symbols-outlined text-on-secondary-container text-3xl\" aria-hidden=\"true\">landscape</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-3xl font-bold mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-3xl font-bold mb-4\">Tiny House Rental</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg text-on-surface-variant mb-8 grow\"} -->\n<p class=\"font-body text-lg text-on-surface-variant mb-8 grow\">Always wanted to stay in a tiny house, a converted double decker or a boat?<br><br>Find here our out-of-the-ordinary stays, available for short- and long term rental.</p>\n<!-- /wp:paragraph -->\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"aspect-video rounded-lg overflow-hidden mb-8\"} -->\n<figure class=\"wp-block-image size-large aspect-video rounded-lg overflow-hidden mb-8\"><img src=\"/wp-content/uploads/2026/05/village-rental.jpg\" alt=\"A cleared grassy plot surrounded by wild flowers and ancient trees, prepared for a eco-friendly tiny home\"/></figure>\n<!-- /wp:image -->\n<!-- wp:paragraph {\"className\":\"mb-0\"} -->\n<p class=\"mb-0\"><a class=\"text-primary font-headline font-bold text-xl flex items-center gap-2 group-hover:translate-x-2 transition-transform duration-300\" href=\"https://bisque-elk-240168.hostingersite.com/booking/\">Find the available rentals <span class=\"material-symbols-outlined\" aria-hidden=\"true\">arrow_right_alt</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div>\n<!-- /wp:column -->\n<!-- wp:column -->\n<div class=\"wp-block-column\">\n<!-- wp:group {\"className\":\"bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full md:scale-105 z-10 group hover:bg-surface-bright transition-colors duration-500\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group bg-surface-container rounded-xl p-8 editorial-shadow flex flex-col h-full md:scale-105 z-10 group hover:bg-surface-bright transition-colors duration-500\">\n<!-- wp:html -->\n<div class=\"w-16 h-16 bg-primary-container rounded-full flex items-center justify-center mb-8 group-hover:scale-110 transition-transform duration-300\"><span class=\"material-symbols-outlined text-on-primary-container text-3xl\" aria-hidden=\"true\">cottage</span></div>\n<!-- /wp:html -->\n<!-- wp:heading {\"level\":3,\"className\":\"font-headline text-3xl font-bold mb-4\"} -->\n<h3 class=\"wp-block-heading font-headline text-3xl font-bold mb-4\">5-year-lease</h3>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"font-body text-lg text-on-surface-variant mb-8 grow\"} -->\n<p class=\"font-body text-lg text-on-surface-variant mb-8 grow\">Have yo