(394,0,'2026-05-07 15:58:02','2026-05-07 15:58:02','<!-- wp:group {\"tagName\":\"div\",\"className\":\"vila-page-inner pt-0 overflow-x-hidden\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group vila-page-inner pt-0 overflow-x-hidden\">\n\n<!-- wp:cover {\"url\":\"/wp-content/uploads/2026/05/booking-hero.jpg\",\"dimRatio\":35,\"overlayColor\":\"black\",\"isUserOverlayColor\":true,\"minHeight\":70,\"minHeightUnit\":\"vh\",\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-position-center-center\" style=\"min-height:70vh\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-35 has-black-background-color\"></span><img class=\"wp-block-cover__image-background size-full\" alt=\"Alentejo cork oak trees at golden hour\" src=\"/wp-content/uploads/2026/05/booking-hero.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\">\n<!-- wp:group {\"className\":\"w-full max-w-[1236px] mx-auto box-border px-8 space-y-6\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group w-full max-w-[1236px] mx-auto box-border px-8 space-y-6\">\n<!-- wp:heading {\"level\":1,\"className\":\"text-5xl md:text-8xl font-normal text-on-primary font-barrio leading-none drop-shadow-lg\"} -->\n<h1 class=\"wp-block-heading text-5xl md:text-8xl font-normal text-on-primary font-barrio leading-none drop-shadow-lg\">Book your stay</h1>\n<!-- /wp:heading -->\n<!-- wp:paragraph {\"className\":\"text-xl md:text-2xl text-on-primary/90 font-light max-w-xl leading-relaxed\"} -->\n<p class=\"text-xl md:text-2xl text-on-primary/90 font-light max-w-xl leading-relaxed\">Whether you\'re looking for a place to stay for the night, for a month or for a lifetime, there is a place for you here with us.</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n</div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"max-w-3xl mx-auto box-border px-6 py-2